      "pattern": "^[^\\u0009-\\u000D\\u0020\\u0085\\u00A0\\u1680\\u2000-\\u200A\\u2028\\u2029\\u202F\\u205F\\u3000\\uFEFF](?:[\\s\\S]*[^\\u0009-\\u000D\\u0020\\u0085\\u00A0\\u1680\\u2000-\\u200A\\u2028\\u2029\\u202F\\u205F\\u3000\\uFEFF])?(?![\\s\\S])",
      "examples": ["ast_7c11"]
    },

    "AssetOrigin": {
      "title": "资产来源 · Asset Origin",
      "description": "S-5：official 或 customized（UL-asset-origin 的两值），闭合。产生这份记录时定死，此后不变；不得靠任何请求自报。",
      "$comment": "未知取值的拒绝值是 origin_unknown（S-27）。",
      "type": "string",
      "enum": ["official", "customized"]
