          "required": ["kind", "organization"],
          "additionalProperties": false
        },
        {
          "title": "租户所有",
          "properties": {
            "kind": { "const": "tenant" },
            "tenant": { "$ref": "../../identity-values/v1/identity-values.schema.json#/$defs/TenantId" }
          },
          "required": ["kind", "tenant"],
          "additionalProperties": false
        }
      ]
    },

    "AssetContent": {
      "title": "一份资产的正文外壳",
      "description": "S-10：按 category 判别的八个变体。tool、loop_extension、skill、mcp、slash_command、connector 六类的正文 $ref 各自的正文契约；agent_definition 本版是不透明壳 { body }，body 的形状归 PF-004 的契约（G-6），在那之前任何一方不得解释它；plugin 的正文是成员能力标识的列表（S-11）。",
      "$comment": "八个变体内联在 oneOf 里，本版不给壳单独的 $defs 名。category 未知的拒绝值是 category_unknown；plugin 成员里有 plugin 的拒绝值是 plugin_member_is_plugin；正文不合它那份正文契约时，拒绝值取那份契约的值、原名携带（S-27）。",
      "type": "object",
      "oneOf": [
        {
          "title": "tool",
          "properties": {
            "category": { "const": "tool" },
            "definition": { "$ref": "../../tool-definition/v2/tool-definition.schema.json#/$defs/ToolDefinition" }
          },
          "required": ["category", "definition"],
          "additionalProperties": false
        },
        {
          "title": "loop_extension",
          "properties": {
