          },
          "required": ["category", "body"],
          "additionalProperties": false
        },
        {
          "title": "mcp",
          "properties": {
            "category": { "const": "mcp" },
            "body": { "$ref": "../../mcp-endpoint/v2/mcp-endpoint.schema.json#/$defs/McpEndpoint" }
          },
          "required": ["category", "body"],
          "additionalProperties": false
        },
        {
          "title": "slash_command",
          "properties": {
            "category": { "const": "slash_command" },
            "body": { "$ref": "../../slash-command/v2/slash-command.schema.json#/$defs/SlashCommandDefinition" }
          },
          "required": ["category", "body"],
          "additionalProperties": false
        },
        {
          "title": "connector",
          "properties": {
            "category": { "const": "connector" },
            "body": { "$ref": "../../connector/v2/connector.schema.json#/$defs/ConnectorDefinition" }
          },
          "required": ["category", "body"],
          "additionalProperties": false
        },
        {
          "title": "agent_definition（不透明壳）",
          "properties": {
            "category": { "const": "agent_definition" },
            "body": { "$comment": "不透明：Agent Definition 的正文归 PF-004 的契约（G-6）。" }
