    "AssetVersion": {
      "title": "资产版本 · Asset Version",
      "description": "S-9：一份资产在某一次发布时定下的那份内容（UL-asset-version）。number 从 1 起、在这份记录的版本线上连续编号；发布之后整条不变。publishedBy 是发布它的租户——customized 资产必有，official 资产必无（由 AssetDefinition 按 origin 约束）。",
      "type": "object",
      "properties": {
        "number": { "type": "integer", "minimum": 1 },
        "content": { "$ref": "#/$defs/AssetContent" },
        "publishedAt": { "$ref": "../../offer-expiry/v1/offer-expiry.schema.json#/$defs/Instant" },
        "publishedBy": { "$ref": "../../identity-values/v1/identity-values.schema.json#/$defs/TenantId" }
      },
      "required": ["number", "content", "publishedAt"],
      "additionalProperties": false
    },

    "LineageId": {
      "title": "血缘号",
      "description": "S-22：一条复制血缘的标识。系统在首次复制时发出；不透明、部署内唯一、不回收不复用；它的值不是源记录号、源组织标识或二者的任何可逆编码，对目标组织的任何读面都不提供从它到源的解引用。交换表示按 data.identity-values v1 S-31 的散文。",
      "type": "string",
      "minLength": 1,
      "pattern": "^[^\\u0009-\\u000D\\u0020\\u0085\\u00A0\\u1680\\u2000-\\u200A\\u2028\\u2029\\u202F\\u205F\\u3000\\uFEFF](?:[\\s\\S]*[^\\u0009-\\u000D\\u0020\\u0085\\u00A0\\u1680\\u2000-\\u200A\\u2028\\u2029\\u202F\\u205F\\u3000\\uFEFF])?(?![\\s\\S])",
      "examples": ["lin_40e9"]
    },

    "CopyLineage": {
      "title": "复制血缘 · Copy Lineage",
      "description": "S-21：目标侧这份资产与它的来源之间的对应关系（UL-copy-lineage）。lineage 在首次复制时产生，此后不变——这就是词条说的「此后不变」的那条对应；sourceVersion、importedBy、importedAt 是最近一次送入的事实（源侧第几版、落地一侧哪个租户、何时），imports 是送入次数，这四项只随一次重复复制改写。它挂在落进目标组织某一层的那一份上，按（源, 落进的那一层）各算各的。importedBy 是最近一次落地的行为人在落点组织里的租户身份——本人型是本人，组织型是确认的那位超管——不是他在源侧的那个。流转语义归 capability.asset-transfer v2，本定义只承载形状（R2-10）。",
      "type": "object",
      "properties": {
        "lineage": { "$ref": "#/$defs/LineageId" },
        "sourceVersion": { "type": "integer", "minimum": 1 },
        "importedBy": { "$ref": "../../identity-values/v1/identity-values.schema.json#/$defs/TenantId" },
        "importedAt": { "$ref": "../../offer-expiry/v1/offer-expiry.schema.json#/$defs/Instant" },
        "imports": { "type": "integer", "minimum": 1 }
      },
      "required": ["lineage", "sourceVersion", "importedBy", "importedAt", "imports"],
      "additionalProperties": false
    },

    "AssetDefinition": {
      "title": "资产记录",
      "description": "S-8：一份具体资产。id 是记录号；capability 是它实现的那个能力标识，记录的一生中不变；origin 产生时定死；customized 的必有 owner、author 与 byAgent（作者与所有者分记，PF-001 §6.7；byAgent 标这份记录是不是本系统里一次 agent 运行产出的，缺席不读作 false），official 的三者都缺席（data.identity-values v1 CS-2）；lineage 只在复制产生的记录上有，产生时就有，此后不增不删；draft 可反复改；versions 是已发布、不可变、从 1 连续编号的版本线。草稿与每一版正文的 category 都等于 capability.category。属性声明不存在这里——它们由正文按类别推出（S-12）。",
      "$comment": "版本编号连续（version_sequence_broken）、作者与所有者同属一个组织、importedBy 的组织等于所有者所在的组织、所有者是租户时 importedBy 就是它，Schema 表达不了，由 S-27 在 Schema 之外判。",
      "type": "object",
      "properties": {
        "id": { "$ref": "#/$defs/AssetRecordId" },
        "capability": { "$ref": "#/$defs/CapabilityId" },
        "origin": { "$ref": "#/$defs/AssetOrigin" },
        "owner": { "$ref": "#/$defs/AssetOwner" },
        "author": { "$ref": "../../identity-values/v1/identity-values.schema.json#/$defs/TenantId" },
        "byAgent": { "type": "boolean" },
        "lineage": { "$ref": "#/$defs/CopyLineage" },
        "draft": { "$ref": "#/$defs/AssetContent" },
        "versions": { "type": "array", "items": { "$ref": "#/$defs/AssetVersion" } }
      },
      "required": ["id", "capability", "origin", "versions"],
      "additionalProperties": false,
      "allOf": [
        {
          "if": { "properties": { "origin": { "const": "customized" } }, "required": ["origin"] },
          "then": {
            "required": ["owner", "author", "byAgent"],
            "properties": { "versions": { "items": { "required": ["publishedBy"] } } }
          }
        },
        {
          "if": { "properties": { "origin": { "const": "official" } }, "required": ["origin"] },
          "then": {
            "not": { "anyOf": [{ "required": ["owner"] }, { "required": ["author"] }, { "required": ["byAgent"] }, { "required": ["lineage"] }] },
            "properties": { "versions": { "items": { "not": { "required": ["publishedBy"] } } } }
          }
        },
        {
          "if": { "required": ["lineage"] },
          "then": {
            "properties": {
              "origin": { "const": "customized" }
            }
          }
        },
        {
          "anyOf": [
            { "required": ["draft"] },
            { "properties": { "versions": { "minItems": 1 } } }
          ]
        },
        { "if": { "properties": { "capability": { "properties": { "category": { "const": "skill" } }, "required": ["category"] } }, "required": ["capability"] },
          "then": { "properties": { "draft": { "properties": { "category": { "const": "skill" } } }, "versions": { "items": { "properties": { "content": { "properties": { "category": { "const": "skill" } } } } } } } } },
        { "if": { "properties": { "capability": { "properties": { "category": { "const": "tool" } }, "required": ["category"] } }, "required": ["capability"] },
          "then": { "properties": { "draft": { "properties": { "category": { "const": "tool" } } }, "versions": { "items": { "properties": { "content": { "properties": { "category": { "const": "tool" } } } } } } } } },
        { "if": { "properties": { "capability": { "properties": { "category": { "const": "mcp" } }, "required": ["category"] } }, "required": ["capability"] },
          "then": { "properties": { "draft": { "properties": { "category": { "const": "mcp" } } }, "versions": { "items": { "properties": { "content": { "properties": { "category": { "const": "mcp" } } } } } } } } },
        { "if": { "properties": { "capability": { "properties": { "category": { "const": "connector" } }, "required": ["category"] } }, "required": ["capability"] },
          "then": { "properties": { "draft": { "properties": { "category": { "const": "connector" } } }, "versions": { "items": { "properties": { "content": { "properties": { "category": { "const": "connector" } } } } } } } } },
        { "if": { "properties": { "capability": { "properties": { "category": { "const": "loop_extension" } }, "required": ["category"] } }, "required": ["capability"] },
          "then": { "properties": { "draft": { "properties": { "category": { "const": "loop_extension" } } }, "versions": { "items": { "properties": { "content": { "properties": { "category": { "const": "loop_extension" } } } } } } } } },
        { "if": { "properties": { "capability": { "properties": { "category": { "const": "slash_command" } }, "required": ["category"] } }, "required": ["capability"] },
          "then": { "properties": { "draft": { "properties": { "category": { "const": "slash_command" } } }, "versions": { "items": { "properties": { "content": { "properties": { "category": { "const": "slash_command" } } } } } } } } },
        { "if": { "properties": { "capability": { "properties": { "category": { "const": "plugin" } }, "required": ["category"] } }, "required": ["capability"] },
          "then": { "properties": { "draft": { "properties": { "category": { "const": "plugin" } } }, "versions": { "items": { "properties": { "content": { "properties": { "category": { "const": "plugin" } } } } } } } } },
        { "if": { "properties": { "capability": { "properties": { "category": { "const": "agent_definition" } }, "required": ["category"] } }, "required": ["capability"] },
          "then": { "properties": { "draft": { "properties": { "category": { "const": "agent_definition" } } }, "versions": { "items": { "properties": { "content": { "properties": { "category": { "const": "agent_definition" } } } } } } } } }
      ]
    },

    "AttributeKind": {
      "title": "属性种类",
      "description": "S-12：一个属性项是设置还是权限（UL-setting、UL-permission），闭合。",
      "type": "string",
      "enum": ["setting", "permission"]
    },

    "SettingCategory": {
      "title": "设置项类别 · Setting Category",
      "description": "S-13：资产声明每一项设置时必须标上的类别（UL-setting-category），恰四个：preference（偏好）、binding（绑定）、placement_identity（落点与身份）、governance（治理），闭合。类别决定这项值能从哪些层来：placement_identity 与 governance 不从工作区来。治理类是本契约保留的 disabled（S-15）加各正文契约推出的治理类项（本版有 data.connector 的触发会话的默认运行模式一项）。",
      "type": "string",
      "enum": ["preference", "binding", "placement_identity", "governance"]
    },

    "AttributeDomain": {
      "title": "属性项的取值域",
      "description": "S-12：设置的取值域开放，由一份 JSON Schema 描述（kind: open，只有锁与不锁两态）；权限的取值域是一个枚举（kind: enum，能收窄成子集，PF-002 §5.4）。values 非空、各不相同。",
      "$comment": "schema 须是一份合法的 Draft 2020-12 JSON Schema（对象或布尔）；元校验 Schema 表达不了，由接收边界兑现（S-27 malformed）。",
      "type": "object",
      "oneOf": [
        {
          "title": "开放取值域（设置）",
          "properties": {
            "kind": { "const": "open" },
            "schema": { "type": ["object", "boolean"] }
          },
          "required": ["kind", "schema"],
          "additionalProperties": false
        },
        {
          "title": "枚举取值域（权限）",
          "properties": {
            "kind": { "const": "enum" },
            "values": {
              "type": "array",
              "minItems": 1,
              "uniqueItems": true,
              "items": { "type": "string", "minLength": 1 }
            }
          },
          "required": ["kind", "values"],
          "additionalProperties": false
        }
      ]
    },

    "AttributeDeclaration": {
      "title": "属性声明",
      "description": "S-12：一份资产自带的一个属性项——项名、是设置还是权限、设置的类别、取值域、作者给的默认值。它由这份资产的正文按类别推出（推出规则归各类正文契约），不作为一个成员存在资产记录上。设置项必带 category、取值域为 open、default 合那份 schema；权限项不带 category、取值域为 enum、default 是 values 里的一个。default 是这一项在设置层序最外一格（出厂默认）上的值；只有 placement_identity 与 governance 类设置项可以不带 default——缺席即没有作者默认，各格都没配时求值得到缺席、读作「未配」（S-12；governance 那一半随 PF-002 rev 20：连接件的触发会话的默认运行模式「作者声明的默认也不算数」）；保留项 disabled 恒带 default: false。项名 disabled 与 usableBy 由本契约保留（S-15、S-36），它们的声明只能是本定义里写死的那一份。",
      "$comment": "「default 合 schema」「权限 default ∈ values」「同一资产内 item 互不相同」Schema 表达不了，由 S-27 在 Schema 之外判为 malformed。",
      "type": "object",
      "properties": {
        "item": { "type": "string", "minLength": 1 },
        "kind": { "$ref": "#/$defs/AttributeKind" },
        "category": { "$ref": "#/$defs/SettingCategory" },
        "domain": { "$ref": "#/$defs/AttributeDomain" },
        "default": true
      },
      "required": ["item", "kind", "domain"],
      "additionalProperties": false,
      "allOf": [
        {
          "if": { "properties": { "kind": { "const": "setting" }, "category": { "enum": ["placement_identity", "governance"] } }, "required": ["kind", "category"] },
          "else": { "required": ["default"] }
        },
        {
          "if": { "properties": { "kind": { "const": "setting" } }, "required": ["kind"] },
          "then": {
            "required": ["category"],
            "properties": { "domain": { "properties": { "kind": { "const": "open" } } } }
          }
        },
        {
          "if": { "properties": { "kind": { "const": "permission" } }, "required": ["kind"] },
          "then": {
            "not": { "required": ["category"] },
            "properties": {
              "domain": { "properties": { "kind": { "const": "enum" } } },
              "default": { "type": "string" }
            }
          }
        },
        {
          "if": { "properties": { "item": { "const": "disabled" } }, "required": ["item"] },
          "then": {
            "required": ["default"],
            "properties": {
              "kind": { "const": "setting" },
              "category": { "const": "governance" },
              "domain": { "const": { "kind": "open", "schema": { "type": "boolean" } } },
              "default": { "const": false }
            }
          }
        },
        {
          "if": { "properties": { "item": { "const": "usableBy" } }, "required": ["item"] },
          "then": {
            "properties": {
              "kind": { "const": "permission" },
              "domain": { "const": { "kind": "enum", "values": ["superAdministrator", "member", "self"] } },
              "default": { "const": "self" }
            }
          }
        }
      ]
    },

    "PermissionValue": {
      "title": "权限的配值",
      "description": "S-14：一层给一个权限项配下的允许集合。它是该项取值域的一个子集，可以为空（收窄为空集，PF-002 §5.3）；选定一个值就是收窄成单元素集。元素各不相同。",
      "type": "object",
      "properties": {
        "allowed": {
          "type": "array",
          "uniqueItems": true,
          "items": { "type": "string", "minLength": 1 }
        }
      },
      "required": ["allowed"],
      "additionalProperties": false
    },

    "AttributeAssignment": {
      "title": "属性配值 · Attribute Assignment",
      "description": "S-14：某一级在一份资产持有上、为一个属性项配下的一个值（UL-attribute-assignment）。设置项的 value 是一个合该项取值域的 JSON 值；权限项的 value 是一个 PermissionValue。immutable 是不可覆盖标记——true 即「必须这样」，更具体的层改不了；它必填，缺席不当作 false。since 是这条配值此刻的值被写下的时刻，只加锁解锁不改它。item 为 disabled 时 value 只能是布尔、immutable 只能是 false（S-15）。",
      "$comment": "value 该是设置值还是 PermissionValue、是否合取值域，要看这份持有所指资产推出的声明，Schema 表达不了（S-27 malformed）；项已不在当前声明里的配值是合法的留存（S-14）。",
      "type": "object",
      "properties": {
        "item": { "type": "string", "minLength": 1 },
        "value": true,
        "immutable": { "type": "boolean" },
        "since": { "$ref": "../../offer-expiry/v1/offer-expiry.schema.json#/$defs/Instant" }
      },
      "required": ["item", "value", "immutable", "since"],
      "additionalProperties": false,
      "if": { "properties": { "item": { "const": "disabled" } }, "required": ["item"] },
      "then": {
        "properties": {
          "value": { "type": "boolean" },
          "immutable": { "const": false }
        }
      }
    },

    "WorkspaceKey": {
      "title": "工作区键",
      "description": "S-17：在一个租户之内指认一份工作区（UL-workspace）的键：(tenant, directory)。tenant 是持有它的租户；directory 是承载目录的绝对路径的规范形式（规范化归实现，本版单机），相等按分量、directory 按字面逐码点。directory 是指认，不是资格（PF-001 §6.5；data.identity-values v1 S-22）。本键闭合 data.identity-values v1 G-07 的「目录那一半」。",
      "$comment": "「绝对、规范形式」与平台相关，Schema 只管到非空字符串；由写下这个键的一方在写入前兑现。",
      "type": "object",
      "properties": {
        "tenant": { "$ref": "../../identity-values/v1/identity-values.schema.json#/$defs/TenantId" },
        "directory": { "type": "string", "minLength": 1 }
      },
      "required": ["tenant", "directory"],
      "additionalProperties": false
    },

    "HoldingScope": {
      "title": "持有范围",
      "description": "S-16：持有与配值的归属格，四格闭合：factory（出厂默认，不带任何身份值）、organization 与 tenant（就是 data.identity-values v1 的 ScopeLayerIdentity 两个变体，原样引用）、workspace（带一个 WorkspaceKey）。它是资产归属那条层序的四格，不是作用域层身份——workspace 与 factory 两格都不是一重身份。会话不是持有层。",
      "$comment": "判别成员统一是 layer；未知取值拒绝值是 malformed（S-27）。不压平成几个可空字段（data.identity-values v1 S-16）。",
      "type": "object",
      "oneOf": [
        {
          "title": "出厂默认",
          "properties": { "layer": { "const": "factory" } },
          "required": ["layer"],
          "additionalProperties": false
        },
        { "$ref": "../../identity-values/v1/identity-values.schema.json#/$defs/ScopeLayerIdentity" },
        {
          "title": "工作区",
          "properties": {
            "layer": { "const": "workspace" },
            "workspace": { "$ref": "#/$defs/WorkspaceKey" }
          },
          "required": ["layer", "workspace"],
          "additionalProperties": false
        }
      ]
    },

    "SharingId": {
      "title": "分享号",
      "description": "S-22：一段确认之后的资产分享（UL-asset-sharing）的标识。由 capability.asset-transfer 在分享被确认时产生；那段分享的含义、状态与生灭归那份契约，本契约只定它的交换表示，供 HoldingBasis 引用。不透明、部署内唯一、不回收不复用；表示按 data.identity-values v1 S-31 的散文。",
      "type": "string",
      "minLength": 1,
      "pattern": "^[^\\u0009-\\u000D\\u0020\\u0085\\u00A0\\u1680\\u2000-\\u200A\\u2028\\u2029\\u202F\\u205F\\u3000\\uFEFF](?:[\\s\\S]*[^\\u0009-\\u000D\\u0020\\u0085\\u00A0\\u1680\\u2000-\\u200A\\u2028\\u2029\\u202F\\u205F\\u3000\\uFEFF])?(?![\\s\\S])",
      "examples": ["shr_0b17"]
    },

    "HoldingBasis": {
      "title": "使用权来路",
      "description": "S-19：这份持有的资格从哪来，五支闭合。owned：持有方就是这份资产的定义所有者（组织、租户格）；organization：外层某一格持有同一份实现，本格为配值或加锁而持有（租户、工作区格）；official：它是 official 资产，不需要授权（任一格）；shared：经一段确认之后的分享获得使用权，带那段分享的 SharingId（组织格或租户格：接收方是组织落组织格，是租户落那个租户的格；此刻生不生效归 capability.asset-transfer）；carrier：工作区从承载目录提供的资产（工作区格）。",
      "$comment": "判别成员 kind 的未知取值拒绝值是 malformed（S-27）。",
      "type": "object",
      "oneOf": [
        {
          "title": "拥有",
          "properties": { "kind": { "const": "owned" } },
          "required": ["kind"],
          "additionalProperties": false
        },
        {
          "title": "外层持有",
          "properties": { "kind": { "const": "organization" } },
          "required": ["kind"],
          "additionalProperties": false
        },
        {
          "title": "官方件",
          "properties": { "kind": { "const": "official" } },
          "required": ["kind"],
          "additionalProperties": false
        },
        {
          "title": "经分享",
          "properties": {
            "kind": { "const": "shared" },
            "sharing": { "$ref": "#/$defs/SharingId" }
          },
          "required": ["kind", "sharing"],
          "additionalProperties": false
        },
        {
          "title": "工作区提供",
          "properties": { "kind": { "const": "carrier" } },
          "required": ["kind"],
          "additionalProperties": false
        }
      ]
    },

    "VersionSelection": {
      "title": "版本选用",
      "description": "S-18：这一格用所指记录的哪一版（UL-version-selection）。current 跟随此刻的最新已发布版；pinned 固定在第 number 版（≥ 1）。新版发布不改任何一份 pinned 持有。",
      "$comment": "判别成员 kind 的未知取值拒绝值是 malformed（S-26、S-27）。pinned 的版本在所指记录的版本线上存在，Schema 表达不了。",
      "type": "object",
      "oneOf": [
        {
          "title": "跟随当前",
          "properties": { "kind": { "const": "current" } },
          "required": ["kind"],
          "additionalProperties": false
        },
        {
          "title": "固定一版",
          "properties": {
            "kind": { "const": "pinned" },
            "number": { "type": "integer", "minimum": 1 }
          },
          "required": ["kind", "number"],
          "additionalProperties": false
        }
      ]
    },

    "AssetHolding": {
      "title": "资产持有 · Asset Holding",
      "description": "S-18：一个持有范围与一份资产之间的持有关系（UL-asset-holding）。键是 (holder, capability)，同一个键至多一份持有；asset 是这一格用的那份实现，它的 capability 必须等于本持有的 capability；basis 是资格来路；versionSelection 是这一格用哪一版；immutable 是锁替换——持有它的这一格以下不许再替换这个能力标识（PF-002 §5.5）；assignments 是这一格为它配下的值，item 互不相同，禁用就是其中名为 disabled 的那一项；since 是这份持有成立的时刻。出厂格只持有 official、不带配值、不加锁；工作区格不加锁、配值不加锁；owned 只在组织与租户格，organization 只在租户与工作区格，shared 只在组织与租户格，carrier 只在工作区格；shared 与 carrier 只选 current；official 的持有上没有 disabled 项（S-20、S-19、S-18、S-15）。",
      "$comment": "同一个键至多一份、asset 与 capability 一致、item 不重复（assignment_item_duplicate）、owned 时所有者等于持有方、organization 时外层确有同一份持有、carrier 时记录是那份工作区提供的、pinned 的版本存在——都要看记录或整个存储，Schema 表达不了（S-27）。工作区格上的权限、落点与身份类、治理类配值形状合法、不是 malformed，由 capability.asset-evaluation 在求值第 4 步滤掉并留痕（S-20，R2-11）。",
      "type": "object",
      "properties": {
        "holder": { "$ref": "#/$defs/HoldingScope" },
        "capability": { "$ref": "#/$defs/CapabilityId" },
        "asset": { "$ref": "#/$defs/AssetRecordId" },
        "basis": { "$ref": "#/$defs/HoldingBasis" },
        "versionSelection": { "$ref": "#/$defs/VersionSelection" },
        "immutable": { "type": "boolean" },
        "assignments": { "type": "array", "items": { "$ref": "#/$defs/AttributeAssignment" } },
        "since": { "$ref": "../../offer-expiry/v1/offer-expiry.schema.json#/$defs/Instant" }
      },
      "required": ["holder", "capability", "asset", "basis", "versionSelection", "immutable", "assignments", "since"],
      "additionalProperties": false,
      "allOf": [
        {
          "if": { "properties": { "holder": { "properties": { "layer": { "const": "factory" } }, "required": ["layer"] } }, "required": ["holder"] },
          "then": {
            "properties": {
              "basis": { "properties": { "kind": { "const": "official" } } },
              "assignments": { "maxItems": 0 }
            }
          }
        },
        {
          "if": { "properties": { "holder": { "properties": { "layer": { "const": "workspace" } }, "required": ["layer"] } }, "required": ["holder"] },
          "then": {
            "properties": {
              "immutable": { "const": false },
              "assignments": { "items": { "properties": { "immutable": { "const": false } } } }
            }
          }
        },
        {
          "if": { "properties": { "basis": { "properties": { "kind": { "const": "shared" } }, "required": ["kind"] } }, "required": ["basis"] },
          "then": {
            "properties": {
              "holder": { "properties": { "layer": { "enum": ["organization", "tenant"] } } },
              "versionSelection": { "properties": { "kind": { "const": "current" } } }
            }
          }
        },
        {
          "if": { "properties": { "basis": { "properties": { "kind": { "const": "owned" } }, "required": ["kind"] } }, "required": ["basis"] },
          "then": { "properties": { "holder": { "properties": { "layer": { "enum": ["organization", "tenant"] } } } } }
        },
        {
          "if": { "properties": { "basis": { "properties": { "kind": { "const": "organization" } }, "required": ["kind"] } }, "required": ["basis"] },
          "then": { "properties": { "holder": { "properties": { "layer": { "enum": ["tenant", "workspace"] } } } } }
        },
        {
          "if": { "properties": { "basis": { "properties": { "kind": { "const": "carrier" } }, "required": ["kind"] } }, "required": ["basis"] },
          "then": {
            "properties": {
              "holder": { "properties": { "layer": { "const": "workspace" } } },
              "versionSelection": { "properties": { "kind": { "const": "current" } } }
            }
          }
        },
        {
          "if": { "properties": { "basis": { "properties": { "kind": { "const": "official" } }, "required": ["kind"] } }, "required": ["basis"] },
          "then": {
            "properties": {
              "assignments": { "not": { "contains": { "properties": { "item": { "const": "disabled" } }, "required": ["item"] } } }
            }
          }
        }
      ]
    },

    "CredentialRef": {
      "title": "凭据引用",
      "description": "S-23：凭据类设置项（MCP 凭据，UL-mcp-credential）的配值值——指向凭据本体的一个不透明引用，不是凭据本身；部署内唯一、不回收不复用。不得为明文；只在它被配上去的那一份持有上有效，抄到另一份持有上不产生取用资格；它本身也不作为呈现内容。凭据本体存在哪、怎么加密、怎么续期归提供者设计。表示按 data.identity-values v1 S-31 的散文。",
      "$comment": "「不是明文」「与那份持有绑定」都是行为约束，Schema 只管到非空、首尾无空白的字符串。",
      "type": "string",
      "minLength": 1,
      "pattern": "^[^\\u0009-\\u000D\\u0020\\u0085\\u00A0\\u1680\\u2000-\\u200A\\u2028\\u2029\\u202F\\u205F\\u3000\\uFEFF](?:[\\s\\S]*[^\\u0009-\\u000D\\u0020\\u0085\\u00A0\\u1680\\u2000-\\u200A\\u2028\\u2029\\u202F\\u205F\\u3000\\uFEFF])?(?![\\s\\S])",
      "examples": ["cred_5a0e"]
    },

    "WorkspaceCarrierManifest": {
      "title": "工作区承载清单",
      "description": "S-24：承载目录里那份特定命名的文件 <目录>/.omne/workspace.json 的形状——一份清单显式列举，不扫目录、不猜文件。format 恒为 1；assets 列出目录内提供的资产包（能力标识 + 相对承载目录的来路）；assignments 是这一级的配值；disabled 是这一级配的禁用（只对本目录提供的资产生效，读入规则归 capability.asset-evaluation）。三个列表都必须在，可以为空。assignments 里写了 immutable、权限项或落点与身份类设置项，不在形状层拒——读入时滤掉并留痕，那是读入方的义务。",
      "$comment": "format 在但不等于 1 的拒绝值是 manifest_format_unsupported，且先于其余一切判定；source 越出承载目录（绝对路径、盘符前缀、含 .. 段、含反斜杠）的拒绝值是 manifest_source_escapes；assets 同一能力标识出现两次是 malformed；assignments 同一 (capability, item) 出现两次是 assignment_item_duplicate（S-27）。",
      "type": "object",
      "properties": {
        "format": { "const": 1 },
        "assets": {
          "type": "array",
          "items": {
            "type": "object",
            "properties": {
              "capability": { "$ref": "#/$defs/CapabilityId" },
              "source": {
                "$comment": "相对承载目录的路径，分隔符只用 '/'；每一段非空；不以 '/' 开头或结尾；没有 '..' 段；不含反斜杠；不以盘符（如 C:）开头。末尾用 (?![\\s\\S]) 判绝对结尾，不用 $。",
                "type": "string",
                "minLength": 1,
                "pattern": "^(?![A-Za-z]:)(?!(?:[\\s\\S]*/)?\\.\\.(?:/|(?![\\s\\S])))[^/\\\\]+(?:/[^/\\\\]+)*(?![\\s\\S])"
              }
            },
            "required": ["capability", "source"],
            "additionalProperties": false
          }
        },
        "assignments": {
          "type": "array",
          "items": {
            "type": "object",
            "properties": {
              "capability": { "$ref": "#/$defs/CapabilityId" },
              "item": { "type": "string", "minLength": 1 },
              "value": true,
              "immutable": { "type": "boolean", "$comment": "允许出现，只为让读入方能看见它、滤掉它并留痕；工作区那一级配不了 immutable（PF-002 §5.2）。" }
            },
            "required": ["capability", "item", "value"],
            "additionalProperties": false
          }
        },
        "disabled": {
          "type": "array",
          "uniqueItems": true,
          "items": { "$ref": "#/$defs/CapabilityId" }
        }
      },
      "required": ["format", "assets", "assignments", "disabled"],
      "additionalProperties": false
    }
  }
}

files..meta_harness/design/spec/data/call-acco:
{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://omne-harness-lite.invalid/meta-harness/omne-harness-lite-design-2026-09-15/spec/data/call-accounts/v2/call-accounts.schema.json",
  "title": "data.call-accounts v2",
  "description": "一次模型调用或一次工具执行的账：用量、费用、逐笔费用、砍了多少、事后补账。本文件只登记共享定义，由消费者以 $ref 引用；根模式不约束任何文档。条款编号 S-n 指同目录的 contract.md，仅在 data.call-accounts/v2 内有效。",
  "$comment": "状态 candidate，未接受、未冻结。Schema 管形状与一部分组合约束；另有几条组合约束 Schema 表达不了（reasoning_tokens ≤ output_tokens、总额恰等于各笔之和、同一 ResponseId 不镜像两次、endedAt ≥ startedAt、TrimSummary 的三式与帧数一式），contract.md S-27 把它们归入 malformed，由校验方在 Schema 之外兑现。Schema 校验失败只说明「拒绝」，是五个拒绝值里的哪一个按 S-27 的次序定。外部引用：Instant 取自 data.offer-expiry v1（S-22）；CallId 取自 data.content-blocks v2（S-14）；TenantId 与 ScopeLayerIdentity 取自 data.identity-values v1（S-5、S-11）。ResponseId 按 data.identity-values v1 S-31 的散文自写形状、不 $ref data.model-response（那份契约引用本契约，反向引用会成环），含义以 data.model-response/v2 S-6 为准。正反实例在同目录 examples.md。",
  "$defs": {
    "Unknown": {
      "title": "未知（contract.md S-4）",
      "description": "这一项存在，但数不出来。它是一个值：不是 0，不是成员缺席，也不是一次失败。拼写与大小写严格——\"Unknown\"、null、\"\" 都不是它（S-29）。",
      "const": "unknown"
    },
    "ResponseId": {
      "title": "ResponseId（contract.md S-16）",
      "description": "一份 ModelResponse 的标识。不透明、部署内唯一、不回收不复用，由模型请求运行时在那一次发出出门时定下；它不是上游的请求号。交换表示按 data.identity-values v1 S-31 的散文：非空字符串；首字符与末字符都不属于该条逐个列出的空白码点集合；逐码点相等，不做任何规范化；消费者不解析其内容。",
      "$comment": "pattern 照 S-31 的显式空白码点集合写否定字符类，末尾用 (?![\\s\\S]) 判绝对结尾，不用 $ 与 \\s——理由与回归用例见 data.identity-values v1 S-31。具体词法（长度、字符集）归实现。",
      "type": "string",
      "minLength": 1,
      "pattern": "^[^\\u0009-\\u000D\\u0020\\u0085\\u00A0\\u1680\\u2000-\\u200A\\u2028\\u2029\\u202F\\u205F\\u3000\\uFEFF](?:[\\s\\S]*[^\\u0009-\\u000D\\u0020\\u0085\\u00A0\\u1680\\u2000-\\u200A\\u2028\\u2029\\u202F\\u205F\\u3000\\uFEFF])?(?![\\s\\S])",
      "examples": [
        "rsp_1a2b"
      ]
    },
    "Usage": {
      "title": "一次发出的 token 用量（contract.md S-6、S-7）",
      "description": "四项必填，各为非负整数或 \"unknown\"。三项输入两两不相交、合起来是这次请求的全部输入：input_tokens 是既不从缓存读出、也不写入缓存的那部分。output_tokens 含推理。reasoning_tokens 是 output_tokens 的子集，上游报了才有，缺席不是零。source=none 时四项全为 \"unknown\" 且没有 reasoning_tokens；source=upstream 时至少一项是数。cache_tokens 与 total_tokens 是派生量，只在条款里定义，不是成员（S-7）。",
      "type": "object",
      "additionalProperties": false,
      "required": [
        "input_tokens",
        "output_tokens",
        "cache_read_tokens",
        "cache_write_tokens",
        "source"
      ],
      "properties": {
        "input_tokens": {
          "description": "输入里既不从缓存读出、也不写入缓存的那部分。",
          "anyOf": [
            {
              "type": "integer",
              "minimum": 0
            },
            {
              "$ref": "#/$defs/Unknown"
            }
          ]
        },
        "output_tokens": {
          "description": "输出，含推理（若有）。",
          "anyOf": [
            {
              "type": "integer",
              "minimum": 0
            },
            {
              "$ref": "#/$defs/Unknown"
            }
          ]
        },
        "cache_read_tokens": {
          "description": "输入里命中缓存、从缓存读出的那部分。",
          "anyOf": [
            {
              "type": "integer",
              "minimum": 0
            },
            {
              "$ref": "#/$defs/Unknown"
            }
          ]
        },
        "cache_write_tokens": {
          "description": "输入里写入缓存的那部分。",
          "anyOf": [
            {
              "type": "integer",
              "minimum": 0
            },
            {
              "$ref": "#/$defs/Unknown"
            }
          ]
        },
        "reasoning_tokens": {
          "description": "output_tokens 里属于推理的那部分；上游报了才有。它没有 \"unknown\" 这个取值：没报就不出现。reasoning_tokens ≤ output_tokens 是 Schema 表达不了的组合约束（S-6、S-27）。",
          "type": "integer",
          "minimum": 0
        },
        "source": {
          "description": "这组数从哪来：upstream 上游随这次发出报回了用量；none 上游没有报回。",
          "enum": [
            "upstream",
            "none"
          ]
        }
      },
      "allOf": [
        {
          "if": {
            "required": [
              "source"
            ],
            "properties": {
              "source": {
                "const": "none"
              }
            }
          },
          "then": {
            "properties": {
              "input_tokens": {
                "$ref": "#/$defs/Unknown"
              },
              "output_tokens": {
                "$ref": "#/$defs/Unknown"
              },
              "cache_read_tokens": {
                "$ref": "#/$defs/Unknown"
              },
              "cache_write_tokens": {
                "$ref": "#/$defs/Unknown"
              }
            },
            "not": {
              "required": [
                "reasoning_tokens"
              ]
            }
          }
        },
        {
          "if": {
            "required": [
              "source"
            ],
            "properties": {
              "source": {
                "const": "upstream"
              }
            }
          },
          "then": {
            "not": {
              "required": [
                "input_tokens",
                "output_tokens",
                "cache_read_tokens",
                "cache_write_tokens"
              ],
              "properties": {
                "input_tokens": {
                  "$ref": "#/$defs/Unknown"
                },
                "output_tokens": {
                  "$ref": "#/$defs/Unknown"
                },
                "cache_read_tokens": {
                  "$ref": "#/$defs/Unknown"
                },
                "cache_write_tokens": {
                  "$ref": "#/$defs/Unknown"
                }
              }
            }
          }
        }
      ],
      "examples": [
        {
          "input_tokens": 1520,
          "output_tokens": 311,
          "cache_read_tokens": 12288,
          "cache_write_tokens": "unknown",
          "reasoning_tokens": 128,
          "source": "upstream"
        }
      ]
    },
    "Cost": {
      "title": "一次发出的费用（contract.md S-8）",
      "description": "cost_usd 是上游随这次发出报回的实际费用，美元，精确十进制、不截断（S-5）；拿不到记 \"unknown\"，绝不是目录估算。upstream_inference_cost_usd 是上游另报的供应商一侧推理实收，报了才有。source：upstream_usage 取自上游报回；later_correction 取自补账，只出现在有效费用里、原账里不会有（S-18、S-22）；none 拿不到——此时 cost_usd 为 \"unknown\" 且没有 upstream_inference_cost_usd。",
      "type": "object",
      "additionalProperties": false,
      "required": [
        "cost_usd",
        "source"
      ],
      "properties": {
        "cost_usd": {
          "anyOf": [
            {
              "type": "number",
              "minimum": 0
            },
            {
              "$ref": "#/$defs/Unknown"
            }
          ]
        },
        "upstream_inference_cost_usd": {
          "type": "number",
          "minimum": 0
        },
        "source": {
          "enum": [
            "upstream_usage",
            "later_correction",
            "none"
          ]
        }
      },
      "allOf": [
        {
          "if": {
            "required": [
              "source"
            ],
            "properties": {
              "source": {
                "const": "none"
              }
            }
          },
          "then": {
            "properties": {
              "cost_usd": {
                "$ref": "#/$defs/Unknown"
              }
            },
            "not": {
              "required": [
                "upstream_inference_cost_usd"
              ]
            }
          }
        },
        {
          "if": {
            "required": [
              "source"
            ],
            "properties": {
              "source": {
                "enum": [
                  "upstream_usage",
                  "later_correction"
                ]
              }
            }
          },
          "then": {
            "properties": {
              "cost_usd": {
                "type": "number"
              }
            }
          }
        }
      ],
      "examples": [
        {
          "cost_usd": 0.004187,
          "source": "upstream_usage"
        },
        {
          "cost_usd": "unknown",
          "source": "none"
        }
      ]
    },
    "CostItem": {
      "title": "一次工具执行里的一笔费用（contract.md S-9、S-10）",
      "description": "service 是谁收的这笔钱：依赖名、MCP 接入点能力标识的规范串（data.asset-model v2 S-3 的 <category>/<name>，例如 mcp/github），或保留字面量 model_call（这次执行经本系统发出的一次模型调用，它是那份 ModelResponse 的镜像，不是权威，S-10）。source 说的是 cost_usd 这个数的来路：none ⇔ cost_usd 为 \"unknown\"；model_response ⇒ service 为 model_call；model_call ⇒ source 为 model_response 或 none，且 reference 必带、形如 ResponseId。quantity 是报账方自报的计量，本契约不解释、不换算、不跨笔相加。",
      "$comment": "接入点那一种写成规范串（恒含 '/'，因而永不等于 model_call）；依赖名与规范串、保留值不相交还要等 data.tool-definition 的依赖名字符集（contract.md G-4）；此处只约束到非空字符串。同一 ResponseId 在一份账里不镜像两次，是跨元素约束，Schema 表达不了（S-27 malformed）。",
      "type": "object",
      "additionalProperties": false,
      "required": [
        "service",
        "cost_usd",
        "source"
      ],
      "properties": {
        "service": {
          "type": "string",
          "minLength": 1
        },
        "cost_usd": {
          "anyOf": [
            {
              "type": "number",
              "minimum": 0
            },
            {
              "$ref": "#/$defs/Unknown"
            }
          ]
        },
        "quantity": {
          "type": "object",
          "additionalProperties": false,
          "required": [
            "amount",
            "unit"
          ],
          "properties": {
            "amount": {
              "type": "number",
              "minimum": 0
            },
            "unit": {
              "type": "string",
              "minLength": 1
            }
          }
        },
        "reference": {
          "type": "string",
          "minLength": 1
        },
        "source": {
          "enum": [
            "tool_reported",
            "service_reported",
            "model_response",
            "none"
          ]
        }
      },
      "allOf": [
        {
          "if": {
            "required": [
              "source"
            ],
            "properties": {
              "source": {
                "const": "none"
              }
            }
          },
          "then": {
            "properties": {
              "cost_usd": {
                "$ref": "#/$defs/Unknown"
              }
            }
          }
        },
        {
          "if": {
            "required": [
              "source"
            ],
            "properties": {
              "source": {
                "enum": [
                  "tool_reported",
                  "service_reported",
                  "model_response"
                ]
              }
            }
          },
          "then": {
            "properties": {
              "cost_usd": {
                "type": "number"
              }
            }
          }
        },
        {
          "if": {
            "required": [
              "source"
            ],
            "properties": {
              "source": {
                "const": "model_response"
              }
            }
          },
          "then": {
            "properties": {
              "service": {
                "const": "model_call"
              }
            }
          }
        },
        {
          "if": {
            "required": [
              "service"
            ],
            "properties": {
              "service": {
                "const": "model_call"
              }
            }
          },
          "then": {
            "required": [
              "reference"
            ],
            "properties": {
              "source": {
                "enum": [
                  "model_response",
                  "none"
                ]
              },
              "reference": {
                "$ref": "#/$defs/ResponseId"
              }
            }
          }
        }
      ],
      "examples": [
        {
          "service": "web_search",
          "cost_usd": 0.005,
          "quantity": {
            "amount": 1,
            "unit": "request"
          },
          "reference": "req-7Hq2",
          "source": "tool_reported"
        },
        {
          "service": "model_call",
          "cost_usd": 0.0021,
          "reference": "rsp_9c1e",
          "source": "model_response"
        }
      ]
    },
    "TrimReason": {
      "title": "一个增量为什么没有原样送达（contract.md S-15）",
      "description": "闭合四值。rate_merged：因速率节流与相邻增量合并送达；frame_too_long：超过长度上限被截短后送达；quota_exhausted：额度用完，此后的增量整个没送达；rejected：被拒收、整个没送达。长度上限、额度与拒收规则不归本契约。data.arrival-events 照抄这四个值，不另列。",
      "enum": [
        "rate_merged",
        "frame_too_long",
        "quota_exhausted",
        "rejected"
      ]
    },
    "TrimSummary": {
      "title": "一条消息的增量到达过程里合并与截掉的汇总（contract.md S-15）",
      "description": "由做合并与截断的那一方计数，没有 \"unknown\"。merged：因合并而不再单独送达的增量个数（n 个合一记 n−1）；cut：整个没送达的增量个数；omittedBytes：被截掉或整个没送达的载荷字节数（文本按 UTF-8，二进制按原字节；合并不计）；byReason：四个 TrimReason 各一项、四项都必须出现。byReason.rate_merged = merged、byReason.quota_exhausted + byReason.rejected = cut、无截无丢则 omittedBytes = 0，这三式 Schema 表达不了（S-27 malformed）。",
      "type": "object",
      "additionalProperties": false,
      "required": [
        "merged",
        "cut",
        "omittedBytes",
        "byReason"
      ],
      "properties": {
        "merged": {
          "type": "integer",
          "minimum": 0
        },
        "cut": {
          "type": "integer",
          "minimum": 0
        },
        "omittedBytes": {
          "type": "integer",
          "minimum": 0
        },
        "byReason": {
          "type": "object",
          "propertyNames": {
            "$ref": "#/$defs/TrimReason"
          },
          "required": [
            "rate_merged",
            "frame_too_long",
            "quota_exhausted",
            "rejected"
          ],
          "additionalProperties": {
            "type": "integer",
            "minimum": 0
          }
        }
      },
      "examples": [
        {
          "merged": 0,
          "cut": 0,
          "omittedBytes": 0,
          "byReason": {
            "rate_merged": 0,
            "frame_too_long": 0,
            "quota_exhausted": 0,
            "rejected": 0
          }
        }
      ]
    },
    "FrameAccount": {
      "title": "一次工具执行发了几帧、砍了多少（contract.md S-11、S-15）",
      "description": "emitted 是工具自己经发帧交出的帧数（一帧的单位见 data.arrival-events v2 S-23 第 1 条）；trims 是这些帧里被合并、被截掉的汇总。一帧都没发是正常形态：emitted = 0、trims 各项为零。",
      "$comment": "merged + cut + byReason.frame_too_long ≤ emitted 只在「每帧至多计一次」的前提下成立（S-15），Schema 表达不了（S-27 malformed）。",
      "type": "object",
      "additionalProperties": false,
      "required": [
        "emitted",
        "trims"
      ],
      "properties": {
        "emitted": {
          "type": "integer",
          "minimum": 0
        },
        "trims": {
          "$ref": "#/$defs/TrimSummary"
        }
      }
    },
    "ToolCallAccount": {
      "title": "一次工具执行的账（contract.md S-11～S-14、S-38、S-39）",
      "description": "一次工具执行恰一份，由工具执行记录携带，不进给模型看的上下文。initiator 是发起这次执行所属运行的租户身份——成本归它；credentialScope 是这次执行的自有费用经哪一格上的凭据产生（本版只有 MCP 凭据，只在租户那一格），没经范围上的凭据就缺席——用量归它（S-38）。externalEffect：confirmed 收场时它在外面的动作已经了结（或根本没开始），unknown 它在外面还可能做了事、花了钱——账上的费用可能不全；哪一次取哪一个值，判据只在 capability.tool-execution-runtime v2 S-14（S-11）。stoppedAt 是写账之前已观察到执行者停下的时刻，写账时还没观察到就缺席（S-14）。late 为 true 表示这份账落下时它归属的尝试已被取代或运行已经终结（S-39）。cost.total_usd：items 全为数时恰等于各笔之和（精确十进制），有一笔 \"unknown\" 就是 \"unknown\"，items 为空时是 0（含义是没记下任何一笔，不是没花钱）；total_usd 含 model_call 镜像，汇总不用它（S-24）。usage 出现当且仅当 items 里有 model_call，是那几份 ModelResponse 的 Usage 的逐项汇总。frames 是 FrameAccount（发了几帧、砍了多少），在途状态丢了时是 \"unknown\"（S-11）。wallClock.endedAt 缺席 ⇔ 写账时没有可记的结束时刻。",
      "$comment": "total_usd 恰等于各笔之和、frames 是 FrameAccount 时 merged + cut + byReason.frame_too_long ≤ emitted（在「每帧至多计一次」的前提下，S-15）、endedAt ≥ startedAt、stoppedAt ≥ startedAt，Schema 表达不了（S-27 malformed）。callId 引用 data.content-blocks v2 的 $defs/CallId。",
      "type": "object",
      "additionalProperties": false,
      "required": [
        "callId",
        "initiator",
        "externalEffect",
        "cost",
        "frames",
        "wallClock"
      ],
      "properties": {
        "callId": {
          "$ref": "../../content-blocks/v2/content-blocks.schema.json#/$defs/CallId"
        },
        "initiator": {
          "$ref": "../../identity-values/v1/identity-values.schema.json#/$defs/TenantId"
        },
        "credentialScope": {
          "description": "ScopeLayerIdentity 的租户那一支：本版只有 MCP 凭据，组织那一层不持有它（PF-002 rev 18 起，S-38）。",
          "allOf": [
            {
              "$ref": "../../identity-values/v1/identity-values.schema.json#/$defs/ScopeLayerIdentity"
            },
            {
              "properties": {
                "layer": {
                  "const": "tenant"
                }
              }
            }
          ]
        },
        "externalEffect": {
          "enum": [
            "confirmed",
            "unknown"
          ]
        },
        "stoppedAt": {
          "$ref": "../../offer-expiry/v1/offer-expiry.schema.json#/$defs/Instant"
        },
        "late": {
          "const": true
        },
        "cost": {
          "type": "object",
          "additionalProperties": false,
          "required": [
            "total_usd",
            "items"
          ],
          "properties": {
            "total_usd": {
              "anyOf": [
                {
                  "type": "number",
                  "minimum": 0
                },
                {
                  "$ref": "#/$defs/Unknown"
                }
              ]
            },
            "items": {
              "type": "array",
              "items": {
                "$ref": "#/$defs/CostItem"
              }
            }
          },
          "if": {
            "required": [
              "items"
            ],
            "properties": {
              "items": {
                "contains": {
                  "required": [
                    "cost_usd"
                  ],
                  "properties": {
                    "cost_usd": {
                      "$ref": "#/$defs/Unknown"
                    }
                  }
                }
              }
            }
          },
          "then": {
            "properties": {
              "total_usd": {
                "$ref": "#/$defs/Unknown"
              }
            }
          }
        },
        "usage": {
          "$ref": "#/$defs/Usage"
        },
        "frames": {
          "description": "FrameAccount，或 \"unknown\"：持有帧计数的在途状态随持有者失去连续性而没了（停机后恢复时追补这份账），发了几帧、砍了多少数不出来——不写 0（S-11）。",
          "oneOf": [
            {
              "$ref": "#/$defs/FrameAccount"
            },
            {
              "$ref": "#/$defs/Unknown"
            }
          ]
        },
        "wallClock": {
          "type": "object",
          "additionalProperties": false,
          "required": [
            "startedAt"
          ],
          "properties": {
            "startedAt": {
              "$ref": "../../offer-expiry/v1/offer-expiry.schema.json#/$defs/Instant"
            },
            "endedAt": {
              "$ref": "../../offer-expiry/v1/offer-expiry.schema.json#/$defs/Instant"
            }
          }
        }
      },
      "if": {
        "required": [
          "cost"
        ],
        "properties": {
          "cost": {
            "required": [
              "items"
            ],
            "properties": {
              "items": {
                "contains": {
                  "required": [
                    "service"
                  ],
                  "properties": {
                    "service": {
                      "const": "model_call"
                    }
                  }
                }
              }
            }
          }
        }
      },
      "then": {
        "required": [
          "usage"
        ]
      },
      "else": {
        "not": {
          "required": [
            "usage"
          ]
        }
      }
    },
    "CostCorrection": {
      "title": "事后补账（contract.md S-17、S-18）",
      "description": "一条独立追加的值，不改原账。target 闭合两种：model_response（一次发出的费用，按 responseId）与 tool_execution（一次工具执行自有部分的费用，按 callId；不是 total_usd，S-17）。cost_usd 必须是数、非负，补账没有 \"unknown\"。obtainedVia：generation_endpoint（按请求号向上游查回，只配 model_response 目标）或 manual。at 是这条补账写下的时刻，在那一次写入里定死。同一目标可有多条，按 at 取最新（S-22）。late 为 true 表示它落下时目标所属的尝试已被取代或运行已经终结（S-39）。",
      "type": "object",
      "additionalProperties": false,
      "required": [
        "target",
        "cost_usd",
        "obtainedVia",
        "at"
      ],
      "properties": {
        "target": {
          "oneOf": [
            {
              "title": "一次发出",
              "type": "object",
              "additionalProperties": false,
              "required": [
                "kind",
                "responseId"
              ],
              "properties": {
                "kind": {
                  "const": "model_response"
                },
                "responseId": {
                  "$ref": "#/$defs/ResponseId"
                }
              }
            },
            {
              "title": "一次工具执行的自有部分",
              "type": "object",
              "additionalProperties": false,
              "required": [
                "kind",
                "callId"
              ],
              "properties": {
                "kind": {
                  "const": "tool_execution"
                },
                "callId": {
                  "$ref": "../../content-blocks/v2/content-blocks.schema.json#/$defs/CallId"
                }
              }
            }
          ]
        },
        "cost_usd": {
          "type": "number",
          "minimum": 0
        },
        "obtainedVia": {
          "enum": [
            "generation_endpoint",
            "manual"
          ]
        },
        "at": {
          "$ref": "../../offer-expiry/v1/offer-expiry.schema.json#/$defs/Instant"
        },
        "late": {
          "const": true
        }
      },
      "if": {
        "required": [
          "obtainedVia"
        ],
        "properties": {
          "obtainedVia": {
            "const": "generation_endpoint"
          }
        }
      },
      "then": {
        "properties": {
          "target": {
            "required": [
              "kind"
            ],
            "properties": {
              "kind": {
                "const": "model_response"
              }
            }
          }
        }
      },
      "examples": [
        {
          "target": {
            "kind": "model_response",
            "responseId": "rsp_2b7f"
          },
          "cost_usd": 0.0039,
          "obtainedVia": "generation_endpoint",
          "at": "2026-09-23T10:05:00Z"
        }
      ]
    },
    "RunId": {
      "title": "RunId（contract.md S-37）",
      "description": "一次运行（UL-run）的标识，供按 Run 汇总与按尝试记明细时指认归属。不透明、会话内唯一、不回收不复用，由 loop 在开始一次运行时产生。交换表示按 data.identity-values v1 S-31 的散文：非空字符串；首末字符不属于该条列出的空白码点集合；逐码点相等，不做规范化；消费者不解析其内容。本定义的家在本契约（主线 2026-09-23 裁定，供 model-response、messages、arrival-events、loop-extension 引用）。",
      "$comment": "pattern 照 S-31 的显式空白码点集合写否定字符类，末尾用 (?![\\s\\S]) 判绝对结尾，不用 $ 与 \\s——理由与回归用例见 data.identity-values v1 S-31。具体词法（长度、字符集）归实现。",
      "type": "string",
      "minLength": 1,
      "pattern": "^[^\\u0009-\\u000D\\u0020\\u0085\\u00A0\\u1680\\u2000-\\u200A\\u2028\\u2029\\u202F\\u205F\\u3000\\uFEFF](?:[\\s\\S]*[^\\u0009-\\u000D\\u0020\\u0085\\u00A0\\u1680\\u2000-\\u200A\\u2028\\u2029\\u202F\\u205F\\u3000\\uFEFF])?(?![\\s\\S])",
      "examples": [
        "run_7f3a"
      ]
    },
    "AttemptId": {
      "title": "AttemptId（contract.md S-37）",
      "description": "一次运行的第几次尝试（UL-run-attempt：尝试的身份是 (运行, 第几次)，不另存），从 1 起的整数序号；与 RunId 合起来才是尝试的完整身份。本定义的家在本契约。",
      "type": "integer",
      "minimum": 1,
      "examples": [
        1,
        2
      ]
    },
    "ModelCallId": {
      "title": "ModelCallId（contract.md S-37）",
      "description": "一次模型调用（UL-model-call）的标识；一次调用可发出多次，各次发出以 (ModelCallId, dispatch) 指认。不透明、会话内唯一（不属于任何运行的调用也有它）、不回收不复用，由模型请求运行时在打开一次新调用时产生。交换表示同 RunId。本定义的家在本契约。",
      "$comment": "pattern 照 S-31 的显式空白码点集合写否定字符类，末尾用 (?![\\s\\S]) 判绝对结尾，不用 $ 与 \\s——理由与回归用例见 data.identity-values v1 S-31。具体词法（长度、字符集）归实现。",
      "type": "string",
      "minLength": 1,
      "pattern": "^[^\\u0009-\\u000D\\u0020\\u0085\\u00A0\\u1680\\u2000-\\u200A\\u2028\\u2029\\u202F\\u205F\\u3000\\uFEFF](?:[\\s\\S]*[^\\u0009-\\u000D\\u0020\\u0085\\u00A0\\u1680\\u2000-\\u200A\\u2028\\u2029\\u202F\\u205F\\u3000\\uFEFF])?(?![\\s\\S])",
      "examples": [
        "mc_3a01"
      ]
    }
  }
}

files..meta_harness/design/spec/data/content-b:
{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://omne-harness-lite.invalid/meta-harness/omne-harness-lite-design-2026-09-15/spec/data/content-blocks/v2/content-blocks.schema.json",
  "title": "data.content-blocks v2",
  "description": "内容块的规范形状。本文件只登记共享定义，由消费者以 $ref 引用；根模式不约束任何文档。条款编号 S-n 指同目录的 contract.md，仅在 data.content-blocks/v2 内有效。",
  "$comment": "状态 candidate，未接受、未冻结。Schema 只管形状；表示层拒绝值（S-26）的具名与优先级、块标识在一条消息内唯一（S-3）、引用形状下两处媒体类型逐字相同（S-10）、落盘后不变（S-22）等由契约条款定，Schema 管不到，逐条列在 contract.md「Schema 管得到什么」。正反实例在同目录 examples.md。不透明标识（BlockId、CallId、AttachmentRef 的 storage 与 key）的交换表示按 data.identity-values/v1#S-31 的散文在本文件写出形状（不跨契约 $ref 那份已冻结契约的 OpaqueIdentifier，它自述不单独被引用；主线裁定，见 D-060 §一 S1-a）；pattern 照 S-31 逐个列出的空白码点写否定字符类，以 (?![\\s\\S]) 判绝对结尾，不用 \\s 与 $——理由与回归用例见 data.identity-values/v1#S-31。",

  "$defs": {

    "BlockId": {
      "type": "string",
      "minLength": 1,
      "pattern": "^[^\\u0009-\\u000D\\u0020\\u0085\\u00A0\\u1680\\u2000-\\u200A\\u2028\\u2029\\u202F\\u205F\\u3000\\uFEFF](?:[\\s\\S]*[^\\u0009-\\u000D\\u0020\\u0085\\u00A0\\u1680\\u2000-\\u200A\\u2028\\u2029\\u202F\\u205F\\u3000\\uFEFF])?(?![\\s\\S])",
      "title": "BlockId",
      "description": "S-3：一个内容块的标识。在一条消息之内唯一——唯一范围是这条消息里出现的全部块，含工具结果块 blocks 里任意层的块与派生表示 blocks 里的块；会话日志里靠 (messageId, id) 指认一个块，messageId 归 data.messages。交换表示与相等按 data.identity-values/v1#S-31 的散文：非空、首尾不属于那个显式空白码点集合、逐码点精确相等、消费者不解析。执行帧里的块由工具侧宿主的帧入口编号（S-3）。它是规格层的名字，不是统一语言词条。",
      "$comment": "「消息内唯一」Schema 表达不了（跨嵌套层的唯一性不是 uniqueItems 能管的），由 S-3 与接收边界的校验兑现。词法形式是缺口 G-4。pattern 的写法见文件头 $comment。",
      "examples": ["b_01", "blk-7f3c"]
    },

    "CallId": {
      "type": "string",
      "minLength": 1,
      "pattern": "^[^\\u0009-\\u000D\\u0020\\u0085\\u00A0\\u1680\\u2000-\\u200A\\u2028\\u2029\\u202F\\u205F\\u3000\\uFEFF](?:[\\s\\S]*[^\\u0009-\\u000D\\u0020\\u0085\\u00A0\\u1680\\u2000-\\u200A\\u2028\\u2029\\u202F\\u205F\\u3000\\uFEFF])?(?![\\s\\S])",
      "title": "CallId",
      "description": "S-14：一次工具调用的标识。在一份会话日志之内，完整的工具调用块（complete: true，含标了 unparseable 的那一种）里它唯一；不嵌在别的工具结果块里的工具结果块，callId 指回那一个——嵌套的工具结果块的 callId 记的是那次执行内部的一次调用，不进这个唯一范围、不指回任何工具调用块。同一个 CallId 可以出现在不止一个工具结果块上（占位与后来到达的真实结果），它们之间的关系归 data.messages。半截的工具调用块上的 callId 只是收到的原值，不是一次已登记调用的标识，任何工具结果块都不指向它。交换表示与相等按 data.identity-values/v1#S-31 的散文。它是规格层的名字，不是统一语言词条。",
      "$comment": "唯一性由登记这次调用的一方保证，Schema 管不到。词法形式是缺口 G-4。pattern 的写法见文件头 $comment。data.call-accounts v2 的 ToolCallAccount.callId 与 CostCorrection 的工具执行目标引用本定义。",
      "examples": ["call_01"]
    },

    "ModelToolName": {
      "title": "模型面名字",
      "description": "S-12：完整工具调用块 tool 的取值——模型面上的工具名，定义名里每一个 : 换成 __；只含 A–Z a–z 0–9 _ -，1～128 个字符。家在 data.tool-definition v2 S-6 的 ModelToolName；本定义是它的逐字副本。",
      "$comment": "互引成环的登记口径（registry README；D-060 §七 M2、M8）：data.tool-definition v2 以 $ref 取本契约的块与附件引用，本契约不反向 $ref 它，在这里逐字写出同一个 type 与 pattern、不登 catalog 依赖；两处逐字对齐是 verification「对齐义务」里的一条。别的契约 $ref data.tool-definition 那一份，不 $ref 这一份。",
      "type": "string",
      "pattern": "^[A-Za-z0-9_-]{1,128}(?![\\s\\S])",
      "examples": ["read_file", "mcp__github__create_issue"]
    },

    "Visibility": {
      "title": "块标注 · Block Annotation",
      "description": "S-4：每个内容块上的两个标注（UL-block-annotation）。toHuman：组装面向人的那一份时取不取它；toModel：组装面向 agent 的那一份时取不取它。两位都必填、互不决定，四种组合都合法。它只说取不取，不说长什么样。由产生这个块的一方在落盘那一刻写下，此后不改（S-22）。缺任一位即表示层拒绝 visibility_missing（S-26），不补默认值。",
      "$comment": "「此刻还给不给模型看」是算出来的——toModel 为真且没被排在前面的压缩记录点名——那一半归 data.messages 与 PF-010，本定义不存它。嵌套块按合取取用见 S-5。",
      "type": "object",
      "properties": {
        "toHuman": { "type": "boolean" },
        "toModel": { "type": "boolean" }
      },
      "required": ["toHuman", "toModel"],
      "additionalProperties": false,
      "examples": [
        { "toHuman": true, "toModel": true },
        { "toHuman": false, "toModel": false }
      ]
    },

    "MediaType": {
      "title": "MediaType",
      "description": "S-7：媒体类型的规范形式——小写的 type/subtype，type 与 subtype 各按 RFC 6838 的 restricted-name 字符集；其后可带若干参数，每个写成紧挨着的 ;name=value，name 小写、value 是 token，不带空白、不带引号。相等只在需要时按整串逐字比较。块的模态只读 type 那一段（S-6），参数原样携带、本契约不解释。",
      "$comment": "要求小写是为了让 S-6 的判定在任何实现上结果相同：大小写不敏感的比较交给各实现，就会出现 TEXT/plain 在一处算文本、在另一处算无模态。产生者写入前自己规范化；接收方不替它改写（S-27）。结尾用 (?![\\s\\S]) 而不是 $，理由同 data.identity-values/v1#S-31：Python 的 $ 会匹配到末尾换行之前。",
      "type": "string",
      "pattern": "^[a-z0-9][a-z0-9!#$&^_.+-]{0,126}/[a-z0-9][a-z0-9!#$&^_.+-]{0,126}(?:;[a-z0-9!#$%&'*+.^_`|~-]+=[A-Za-z0-9!#$%&'*+.^_`|~-]+)*(?![\\s\\S])",
      "examples": ["image/png", "audio/pcm;rate=24000", "video/mp4", "application/pdf"]
    },

    "Modality": {
      "title": "模态 · Modality",
      "description": "S-6：一类内容的形态（UL-modality），恰四种。token 与词条的对应：text ↔ 文本 Text，image ↔ 图 Image，audio ↔ 语音 Voice，video ↔ 视频 Video。块上不存模态——它由块的类型与媒体类型按 S-6 算出；本定义是模态的唯一定义，需要写出模态的消费者（工具定义的模态声明、模型档案的输入输出模态、模态投影）一律 $ref 它，不另列一份。「无模态」不是第五个取值，也不写成 null。",
      "type": "string",
      "enum": ["text", "image", "audio", "video"]
    },

    "CapabilityId": {
      "title": "能力标识 · Capability Identifier",
      "description": "S-20：资产的身份——类别加 name（UL-capability-identifier）。category 恰八类，闭合。相等按两个分量逐码点比较。它是能力标识形状与相等的唯一定义，其他契约一律 $ref 它（本契约自己的块上本版不出现它：DerivedRendering.producedBy 本版恒为 system，S-20）。",
      "$comment": "name 的词法（不含空白与 '/'，冒号允许）归 data.asset-model v2 的 S-2（它以 allOf 在本定义之上收紧 name）；本定义只约束到非空字符串——本契约不反向引用那份契约，以免成环（S-20）。",
      "type": "object",
      "properties": {
        "category": {
          "type": "string",
          "enum": ["skill", "tool", "mcp", "connector", "loop_extension", "slash_command", "plugin", "agent_definition"]
        },
        "name": { "type": "string", "minLength": 1 }
      },
      "required": ["category", "name"],
      "additionalProperties": false,
      "examples": [{ "category": "loop_extension", "name": "image-describer" }]
    },

    "AttachmentRef": {
      "title": "AttachmentRef",
      "description": "S-21：指向某个存储里的一份字节的引用——引用，不是内容。storage 指认是哪一个存储，key 是那份字节在该存储里的键，二者合起来就是相等依据：两个引用相等当且仅当 storage 与 key 都逐码点相等；mediaType、bytes、name 不参与相等。bytes 若给出，是被引用那份字节的长度，只作说明；name 是给人看的名字，不是身份。storage 与 key 对存储之外的任何一方不透明，不得被解析出归属或资格（data.identity-values/v1#S-34：地址不是身份）。它被文件块、语音块与图块的引用形状、以及工具结果块的 offloaded 共用。",
      "$comment": "存储本身全系统尚未定义——storage 取哪些值、引用能否跨节点解引用、解引用时由谁按调用方的租户身份判定能不能读，都等缺口 G-1（owner PF-006）。本定义只定引用的形状与相等。storage 与 key 按 data.identity-values/v1#S-31 的散文表示（pattern 写法见文件头 $comment）。一个只给了引用的附件落成哪一类块见 S-34。",
      "type": "object",
      "properties": {
        "storage": { "type": "string", "minLength": 1, "pattern": "^[^\\u0009-\\u000D\\u0020\\u0085\\u00A0\\u1680\\u2000-\\u200A\\u2028\\u2029\\u202F\\u205F\\u3000\\uFEFF](?:[\\s\\S]*[^\\u0009-\\u000D\\u0020\\u0085\\u00A0\\u1680\\u2000-\\u200A\\u2028\\u2029\\u202F\\u205F\\u3000\\uFEFF])?(?![\\s\\S])" },
        "key": { "type": "string", "minLength": 1, "pattern": "^[^\\u0009-\\u000D\\u0020\\u0085\\u00A0\\u1680\\u2000-\\u200A\\u2028\\u2029\\u202F\\u205F\\u3000\\uFEFF](?:[\\s\\S]*[^\\u0009-\\u000D\\u0020\\u0085\\u00A0\\u1680\\u2000-\\u200A\\u2028\\u2029\\u202F\\u205F\\u3000\\uFEFF])?(?![\\s\\S])" },
        "mediaType": { "$ref": "#/$defs/MediaType" },
        "bytes": { "type": "integer", "minimum": 0 },
        "name": { "type": "string", "minLength": 1 }
      },
      "required": ["storage", "key", "mediaType"],
      "additionalProperties": false,
      "examples": [
        { "storage": "attachments", "key": "obj_5f2c", "mediaType": "image/png", "bytes": 20480 },
        { "storage": "attachments", "key": "obj_91aa", "mediaType": "video/mp4", "name": "demo.mp4" }
      ]
    },

    "InlineBytes": {
      "title": "InlineBytes",
      "description": "S-10：内联在值里的一份字节的 base64 串——标准字母表（RFC 4648 §4）、带填充、非空、不含换行与空白。语音块与图块的内联形状是 { inline: InlineBytes }；别的契约需要在值里内联一份字节（例如工具定义里卸载的内联原始结果）时，承载它的那一成员一律 $ref 本定义，不另写一份编码规则。它是规格层的名字，不是统一语言词条。",
      "$comment": "只定编码规则，不带媒体类型——媒体类型由承载它的那一处给出（语音块、图块的 mediaType；卸载原始结果旁的 mediaType）。结尾用 (?![\\s\\S]) 而不是 $，理由同 MediaType。",
      "type": "string",
      "contentEncoding": "base64",
      "pattern": "^(?:[A-Za-z0-9+/]{4})*(?:[A-Za-z0-9+/]{4}|[A-Za-z0-9+/]{3}=|[A-Za-z0-9+/]{2}==)(?![\\s\\S])",
      "examples": ["iVBORw0KGgo="]
    },

    "DerivedRendering": {
      "title": "派生表示 · Derived Rendering",
      "description": "S-19、S-20：模态转换件从一个块产出、挂在那个原块上的一组别的模态的块（UL-derived-rendering）。它是原块的属性，不是消息里另外的块；在落盘之前写好，之后不变。blocks 至少一块，只能是文本块、图块或语音块——不能是文件块（PF-013 转换件契约），也不能是思考、工具调用或工具结果块；这些块自己不再带派生表示或 transcript。producedBy 是产出它的那一件：本版恒为字面量 system——转换件本版不是资产，只由系统装配层登记（S-20；PF-013 §4 转换件、PF-012 §4 拓展件的例外）。每一块的模态都不同于原块的模态（原块没有模态时不受此限），这一条跨成员比较，Schema 管不到（S-19）。",
      "$comment": "这些块照样带 id 与 visibility：id 与消息里其余块共用一个唯一范围（S-3），visibility 与原块按合取生效（S-5）。组装时取哪一份归 PF-010，本定义不给它们排优先级。",
      "type": "object",
      "properties": {
        "producedBy": { "const": "system" },
        "blocks": {
          "type": "array",
          "minItems": 1,
          "items": {
            "allOf": [
              { "$ref": "#/$defs/ContentBlock" },
              {
                "properties": { "kind": { "enum": ["text", "image", "voice"] } },
                "required": ["kind"]
              },
              { "not": { "anyOf": [{ "required": ["renderings"] }, { "required": ["transcript"] }] } }
            ]
          }
        }
      },
      "required": ["producedBy", "blocks"],
      "additionalProperties": false
    },

    "BlockBase": {
      "title": "块底座",
      "description": "S-2：每一类块共有的成员。id（S-3）与 visibility（S-4）必填；renderings 与 transcript 是模态转换件写在原块上的两样属性（S-19），只有语音块、图块、文件块可以带——其余四类由各自的定义拒绝。二者同有同无（转换件每次都交出至少一块派生表示外加 transcript）；都在落盘前写好、之后不变（S-22）。",
      "$comment": "判别成员 kind 由各类块自己声明。本定义不带 additionalProperties: false——各类块以 allOf 引用它，并以 unevaluatedProperties: false 闭合自己的成员集合。",
      "type": "object",
      "properties": {
        "id": { "$ref": "#/$defs/BlockId" },
        "visibility": { "$ref": "#/$defs/Visibility" },
        "renderings": {
          "type": "array",
          "minItems": 1,
          "items": { "$ref": "#/$defs/DerivedRendering" }
        },
        "transcript": { "type": "string", "minLength": 1 }
      },
      "required": ["id", "visibility"],
      "dependentRequired": { "renderings": ["transcript"], "transcript": ["renderings"] }
    },

    "TextBlock": {
      "title": "文本块",
      "description": "S-8：给人和模型看的一段话。text 可以是空串。origin 是可选的来路标记（统一语言 UL-origin-tag；不是来源标记），恰四种：slash_command_args 表示这块是人敲斜杠命令时附带的参数；skill_body 表示这块是 ② 型（技能型）斜杠命令逐字展开的那个 skill 的正文；slash_command_expansion 表示这块是 ① 型（提示词型）斜杠命令展开模板得到的文字；slash_command_record 表示这块是一次 ①／② 型斜杠命令的留痕——text 是人敲下的那段原文，逐字。command 与 skill 是相应的命令名与 skill 名。来路标记只陈述出处，不授予任何资格，也不改变这块的标注。不带派生表示与 transcript。",
      "type": "object",
      "allOf": [{ "$ref": "#/$defs/BlockBase" }],
      "properties": {
        "kind": { "const": "text" },
        "text": { "type": "string" },
        "origin": {
          "type": "object",
          "properties": {
            "kind": { "type": "string", "enum": ["slash_command_args", "skill_body", "slash_command_expansion", "slash_command_record"] },
            "command": { "type": "string", "minLength": 1 },
            "skill": { "type": "string", "minLength": 1 }
          },
          "required": ["kind"],
          "additionalProperties": false
        }
      },
      "required": ["kind", "text"],
      "not": { "anyOf": [{ "required": ["renderings"] }, { "required": ["transcript"] }] },
      "unevaluatedProperties": false
    },

    "ThinkingBlock": {
      "title": "思考块",
      "description": "S-9：模型的推理过程，与它给人看的话分开。text 可以是空串（上游只给了不透明数据的情形）。opaque 可选、可以是任意 JSON 值（含 null）：由传输适配层写、只由它读；其余每一层都不透明地对待它、不解释它、原样保存并原样回传。缺席与 null 是两件事，各自原样保留。不带派生表示与 transcript。",
      "$comment": "「原样」指同一个 JSON 值，数值不得在任何一跳丢精度。opaque 的内部形状归传输适配，本契约刻意不给结构。",
      "type": "object",
      "allOf": [{ "$ref": "#/$defs/BlockBase" }],
      "properties": {
        "kind": { "const": "thinking" },
        "text": { "type": "string" },
        "opaque": {}
      },
      "required": ["kind", "text"],
      "not": { "anyOf": [{ "required": ["renderings"] }, { "required": ["transcript"] }] },
      "unevaluatedProperties": false
    },

    "VoiceBlock": {
      "title": "语音块",
      "description": "S-10：说出来的话。mediaType 必填且其 type 必须是 audio（模态为 audio）。data 恰为两种可判别形状之一：内联字节 { inline: InlineBytes }，或一个 AttachmentRef——后者的 mediaType 同样必须是 audio/*，并且与块的 mediaType 逐字相同（后一半 Schema 管不到，见 S-10）。可以带派生表示与 transcript。",
      "$comment": "内联形状 { inline } 的串是 $defs/InlineBytes，与 ImageBlock 相同。「执行帧里的媒体块只许引用」是 data.arrival-events 的规则，本定义只把两种形状做成可判别。",
      "type": "object",
      "allOf": [{ "$ref": "#/$defs/BlockBase" }],
      "properties": {
        "kind": { "const": "voice" },
        "mediaType": { "$ref": "#/$defs/MediaType", "pattern": "^audio/" },
        "data": {
          "oneOf": [
            {
              "title": "内联字节",
              "type": "object",
              "properties": { "inline": { "$ref": "#/$defs/InlineBytes" } },
              "required": ["inline"],
              "additionalProperties": false
            },
            {
              "title": "引用",
              "$ref": "#/$defs/AttachmentRef",
              "properties": { "mediaType": { "pattern": "^audio/" } }
            }
          ]
        }
      },
      "required": ["kind", "mediaType", "data"],
      "unevaluatedProperties": false
    },

    "ImageBlock": {
      "title": "图块",
      "description": "S-10：图片本身。mediaType 必填且其 type 必须是 image（模态为 image）。data 恰为两种可判别形状之一：内联字节 { inline: InlineBytes }，或一个 AttachmentRef——后者的 mediaType 同样必须是 image/*，并且与块的 mediaType 逐字相同（后一半 Schema 管不到，见 S-10）。可以带派生表示与 transcript。",
      "$comment": "内联形状 { inline } 的串是 $defs/InlineBytes，与 VoiceBlock 相同。",
      "type": "object",
      "allOf": [{ "$ref": "#/$defs/BlockBase" }],
      "properties": {
        "kind": { "const": "image" },
        "mediaType": { "$ref": "#/$defs/MediaType", "pattern": "^image/" },
        "data": {
          "oneOf": [
            {
              "title": "内联字节",
              "type": "object",
              "properties": { "inline": { "$ref": "#/$defs/InlineBytes" } },
              "required": ["inline"],
              "additionalProperties": false
            },
            {
              "title": "引用",
              "$ref": "#/$defs/AttachmentRef",
              "properties": { "mediaType": { "pattern": "^image/" } }
            }
          ]
        }
      },
      "required": ["kind", "mediaType", "data"],
      "unevaluatedProperties": false
    },

    "FileBlock": {
      "title": "文件块",
      "description": "S-11：一个附件的引用，不是文件内容。attachment 必填。块的模态看 attachment.mediaType（S-6）：是视频它就是视频模态，是一份文档（type 不在四种之内）它就没有模态、只是一个引用。视频没有自己的块类型，装在这里。可以带派生表示与 transcript。",
      "type": "object",
      "allOf": [{ "$ref": "#/$defs/BlockBase" }],
      "properties": {
        "kind": { "const": "file" },
        "attachment": { "$ref": "#/$defs/AttachmentRef" }
      },
      "required": ["kind", "attachment"],
      "unevaluatedProperties": false
    },

    "ToolCallBlock": {
      "title": "工具调用块（完整）",
      "description": "S-12：模型要调哪个工具、传什么参数，参数已经收齐、在封口那一下解析过一次。complete 恒为 true。callId（S-14）、tool（模型面名字 ModelToolName——模型面那个工具条目的 name；多命令工具的子命令在参数里）必填；参数恰为两种之一：解析成功——arguments（解析得到的 JSON 值，任意类型），不带原始参数串；解析不了——rawArguments（收齐的原文）与 unparseable: true 两者同现，不带 arguments。标了 unparseable 的调用同样是一次已登记的调用（callId 进 S-14 的唯一范围），它不被执行，由宿主紧接一条收场为 failed 的结果回给模型；任何一方都不再解析它的 rawArguments。四种标注组合都合法。不带派生表示与 transcript。",
      "$comment": "unparseable 这一种：参数收齐却解析不了的调用保留原文、不执行、结果记 failed 并回给模型（PF-006 §5.5；形状见 D-060 §一 S1-e）。rawArguments 与 unparseable 缺一，或与 arguments 同现，都是 malformed（S-26）。",
      "type": "object",
      "allOf": [
        { "$ref": "#/$defs/BlockBase" },
        {
          "oneOf": [
            {
              "title": "解析成功",
              "required": ["arguments"],
              "not": { "anyOf": [{ "required": ["rawArguments"] }, { "required": ["unparseable"] }] }
            },
            {
              "title": "解析不了",
              "required": ["rawArguments", "unparseable"],
              "not": { "required": ["arguments"] }
            }
          ]
        }
      ],
      "properties": {
        "kind": { "const": "tool_call" },
        "complete": { "const": true },
        "callId": { "$ref": "#/$defs/CallId" },
        "tool": { "$ref": "#/$defs/ModelToolName" },
        "arguments": {},
        "rawArguments": { "type": "string" },
        "unparseable": { "const": true }
      },
      "required": ["kind", "complete", "callId", "tool"],
      "not": { "anyOf": [{ "required": ["renderings"] }, { "required": ["transcript"] }] },
      "unevaluatedProperties": false
    },

    "IncompleteToolCallBlock": {
      "title": "工具调用块（半截）",
      "description": "S-13：参数没收齐的工具调用——记下来，但两边都不给看。complete 恒为 false；rawArguments 是收到的那段原始参数串（可以是空串），任何一方都不解析它；callId 与 tool 是收到的原值，没到就缺席。visibility 必须是 { toHuman: false, toModel: false }，任一位为真即表示层拒绝 incomplete_call_visible（S-26）。它不是一次已登记的调用，任何工具结果块都不指向它。不带派生表示与 transcript。",
      "type": "object",
      "allOf": [{ "$ref": "#/$defs/BlockBase" }],
      "properties": {
        "kind": { "const": "tool_call" },
        "complete": { "const": false },
        "callId": { "$ref": "#/$defs/CallId" },
        "tool": { "type": "string", "minLength": 1 },
        "rawArguments": { "type": "string" },
        "visibility": {
          "properties": {
            "toHuman": { "const": false },
            "toModel": { "const": false }
          }
        }
      },
      "required": ["kind", "complete", "rawArguments"],
      "not": { "anyOf": [{ "required": ["renderings"] }, { "required": ["transcript"] }] },
      "unevaluatedProperties": false
    },

    "ExecutionOutcome": {
      "title": "执行收场 · Execution Outcome",
      "description": "S-17：一次工具执行的终局，恰六种（UL-execution-outcome），闭合。token 与词条的对应：completed ↔ 完成 Completed，failed ↔ 失败 Failed，unavailable ↔ 不可用 Unavailable，backgrounded ↔ 转后台 Moved to Background，interrupted ↔ 被中断 Interrupted，no_answer ↔ 等不到应答 No Reply。",
      "type": "string",
      "enum": ["completed", "failed", "unavailable", "backgrounded", "interrupted", "no_answer"]
    },

    "PlaceholderReason": {
      "title": "PlaceholderReason",
      "description": "S-18：占位原因（统一语言 UL-placeholder-reason），恰十一个；各自落在哪一种收场是写死的：backgrounded_auto、backgrounded_by_user、backgrounded_by_preemption、backgrounded_at_start → backgrounded；user_interrupted、interrupted_by_preemption、human_declined、session_archived、run_cancelled、foreground_timeout → interrupted；abnormal_interruption → failed。取值名是规格层的；它们对应 PF-006 §6.7「占位消息一律要说清原因」表里的行。本定义只描述占位那一侧（D-060 §七 M22）：工具结果块 reason.code 的 Schema 取值是这十一个外加 terminated_by_agent；同一组 token 写在后台那段执行收场的提醒的结果块上时，说的是那段执行为什么这样收场、不是占位原因，那一侧哪几个值合法归 capability.tool-execution-runtime v2 S-10；terminated_by_agent 只在那一侧出现（S-18）。",
      "type": "string",
      "enum": [
        "user_interrupted",
        "backgrounded_auto",
        "backgrounded_by_user",
        "backgrounded_by_preemption",
        "interrupted_by_preemption",
        "human_declined",
        "session_archived",
        "abnormal_interruption",
        "backgrounded_at_start",
        "run_cancelled",
        "foreground_timeout"
      ]
    },

    "ToolResultBlock": {
      "title": "工具结果块",
      "description": "S-15～S-18：一次工具调用的结果，收场带在块上。callId 指回那次调用（S-14）；outcome 是这次收场的唯一依据（S-17），缺席即表示层拒绝，从不当作 completed；reason 在占位上是占位原因、在后台收场提醒的结果块上是那段执行的收场原因（那一侧哪几个值合法归 capability.tool-execution-runtime v2 S-10）——backgrounded 与 interrupted 必带、failed 可带且只能是 abnormal_interruption、其余三种不带，code 必须落在它那一格（S-18）；blocks 是进上下文的内容，它自己又是一串块（可以是空数组，次序有意义），任意一层都不得含工具调用块（S-16）；offloaded 可选，指向被卸载的原始结果——此时 blocks 装的是摘要与取全文的办法，这一块就是那次调用的结果，不是占位（data.messages v2 S-11）。不带派生表示与 transcript——它里面的块各自可以带。",
      "type": "object",
      "allOf": [
        { "$ref": "#/$defs/BlockBase" },
        {
          "if": { "properties": { "outcome": { "const": "backgrounded" } }, "required": ["outcome"] },
          "then": {
            "required": ["reason"],
            "properties": { "reason": { "properties": { "code": { "enum": ["backgrounded_auto", "backgrounded_by_user", "backgrounded_by_preemption", "backgrounded_at_start"] } } } }
          }
        },
        {
          "if": { "properties": { "outcome": { "const": "interrupted" } }, "required": ["outcome"] },
          "then": {
            "required": ["reason"],
            "properties": { "reason": { "properties": { "code": { "enum": ["user_interrupted", "interrupted_by_preemption", "human_declined", "session_archived", "run_cancelled", "terminated_by_agent", "foreground_timeout"] } } } }
          }
        },
        {
          "if": { "properties": { "outcome": { "const": "failed" } }, "required": ["outcome"] },
          "then": {
            "properties": { "reason": { "properties": { "code": { "const": "abnormal_interruption" } } } }
          }
        },
        {
          "if": { "properties": { "outcome": { "enum": ["completed", "unavailable", "no_answer"] } }, "required": ["outcome"] },
          "then": { "not": { "required": ["reason"] } }
        }
      ],
      "properties": {
        "kind": { "const": "tool_result" },
        "callId": { "$ref": "#/$defs/CallId" },
        "outcome": { "$ref": "#/$defs/ExecutionOutcome" },
        "reason": {
          "type": "object",
          "properties": {
            "code": {
              "$comment": "S-18：十一个 token（写在占位上时是占位原因），外加只落后台收场提醒结果块的 terminated_by_agent（不是占位原因）。块自己看不出它在哪一侧，由写入方兑现；后台收场提醒那一侧的取值域归 capability.tool-execution-runtime v2 S-10。",
              "anyOf": [ { "$ref": "#/$defs/PlaceholderReason" }, { "const": "terminated_by_agent" } ]
            },
            "text": { "type": "string", "minLength": 1 }
          },
          "required": ["code", "text"],
          "additionalProperties": false
        },
        "blocks": {
          "type": "array",
          "items": {
            "allOf": [
              { "$ref": "#/$defs/ContentBlock" },
              { "not": { "properties": { "kind": { "const": "tool_call" } }, "required": ["kind"] } }
            ]
          }
        },
        "offloaded": { "$ref": "#/$defs/AttachmentRef" }
      },
      "required": ["kind", "callId", "outcome", "blocks"],
      "not": { "anyOf": [{ "required": ["renderings"] }, { "required": ["transcript"] }] },
      "unevaluatedProperties": false
    },

    "ContentBlock": {
      "title": "内容块 · Content Block",
      "description": "S-1：一条消息装的那串块里的一块（UL-content-block）。按 kind 判别，恰七类：text、thinking、voice、image、file、tool_call、tool_result；tool_call 再按 complete 分完整与半截两种形状，所以一共八个形状、每个值恰合其一。kind 取值闭合：视频不另立块，装在 file 里；未知取值是表示层拒绝 kind_unknown（S-26），不降级成最接近的一类。",
      "oneOf": [
        { "$ref": "#/$defs/TextBlock" },
        { "$ref": "#/$defs/ThinkingBlock" },
        { "$ref": "#/$defs/VoiceBlock" },
        { "$ref": "#/$defs/ImageBlock" },
        { "$ref": "#/$defs/FileBlock" },
        { "$ref": "#/$defs/ToolCallBlock" },
        { "$ref": "#/$defs/IncompleteToolCallBlock" },
        { "$ref": "#/$defs/ToolResultBlock" }
      ]
    }
  }
}

files..meta_harness/design/spec/data/identity-:
{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://omne-harness-lite.invalid/meta-harness/omne-harness-lite-design-2026-09-15/spec/data/identity-values/v1/identity-values.schema.json",
  "title": "data.identity-values v1",
  "description": "身份值的规范形状。本文件只登记共享定义，由消费者以 $ref 引用；根模式不约束任何文档。条款编号 S-n 指同目录的 contract.md，仅在 data.identity-values/v1 内有效。",
  "$comment": "状态 candidate，未接受、未冻结。Schema 只管形状；隔离义务 S-16～S-30 约束的是各 owner 的访问路径与判定，Schema 一概管不到，由静态检查与消费者契约兑现。正反实例在同目录 examples.md。",

  "$defs": {

    "OpaqueIdentifier": {
      "title": "不透明标识（内部基定义）",
      "description": "S-1、S-3、S-9、S-31：不透明、部署内唯一、由存储生成的标识。交换表示是非空字符串，禁止首尾空白；相等是逐码点精确相等，不做 Unicode 规范化、大小写折叠或首尾裁剪。消费者不得解析其内容推断注册时间、顺序或归属，也不得做除相等之外的比较。它不来自运行时对象（如 Cordis 的 Fiber.uid）。本定义不单独被引用，只供下面各具体标识复用。",
      "$comment": "字符集、长度与生成方式是已知缺口 G-04，留 realization。此处只约束到「非空、无首尾空白的字符串」，不补造格式；实现不得把这里的宽松当作「任意字符串都是合法标识」。pattern 刻意不用 \\s 与 $：\\s 的成员在不同引擎里不同（ECMA-262 含 U+FEFF、Python 不含），而 Python 的 $ 还会匹配到「末尾换行之前」，于是同一个串会被两个实现一收一拒。这里改用 S-31 写死的显式空白码点集合（U+0009–000D、U+0020、U+0085、U+00A0、U+1680、U+2000–200A、U+2028、U+2029、U+202F、U+205F、U+3000、U+FEFF）的否定字符类，并以 (?![\\s\\S]) 作绝对结尾断言——[\\s\\S] 的并集在任何引擎下都是全字符集，因此这个否定前瞻只在真正的字符串末尾成立。回归用例：examples.md 第 1 节的尾随换行与前导 U+FEFF 两条反例。",
      "type": "string",
      "minLength": 1,
      "pattern": "^[^\\u0009-\\u000D\\u0020\\u0085\\u00A0\\u1680\\u2000-\\u200A\\u2028\\u2029\\u202F\\u205F\\u3000\\uFEFF](?:[\\s\\S]*[^\\u0009-\\u000D\\u0020\\u0085\\u00A0\\u1680\\u2000-\\u200A\\u2028\\u2029\\u202F\\u205F\\u3000\\uFEFF])?(?![\\s\\S])"
    },

    "HandoffWarrant": {
      "$ref": "#/$defs/OpaqueIdentifier",
      "title": "交接凭证 · Handoff Warrant",
      "description": "S-35：一步操作交给下一步的凭证，断言「我这一步已经做完」，不断言别的。它不是身份值——不指认任何对象，不得作任何记录的键。形状与不透明标识同形：非空、首尾无空白、逐码点精确相等、核实方不解析其内容。六条性质里 Schema 一条也管不到：由哪一步产出、绑定哪个对象标识（本版两个实例都绑 AccountId，不绑定尝试、本版不作废，重放安全由核实方在自己提交里的前置现读承担）、核实方核实存在/绑定/由产出方签发、核实方不核实它断言的领域事实——全部是行为约束，归产出方与核实方各自的契约。",
      "$comment": "绑定字段（凭证里怎么承载 AccountId）的形状由 realization 定，本 Schema 只约束到非空字符串，刻意不给结构：给了结构就等于邀请核实方去解析它，而里面的内容是产出方写的，解析出来的东西证明不了任何事。不可伪造同样管不到——它是 S-35 的契约承诺，单机由装配给（同进程 nonce 登记），跨进程须由协议重新兑现（签名或共享登记），见 contract.md 第六节。本版的两个实例：激活依据（composition.account-registration 于 capability.organization-governance#S-20 成功时产出，capability.account-identity#S-14 核实）、清除依据（capability.organization-governance#S-53 成功含幂等成功时产出，capability.account-identity#S-38 核实）。",
      "examples": ["whf_2a91c07e"]
    },

    "LoginIdentifier": {
      "$ref": "#/$defs/OpaqueIdentifier",
      "title": "登录标识 · Login Identifier",
      "description": "S-2：账号的一项属性（UL-login-identifier），用来指认这个账号的对外名字。整个部署内唯一，注册时确定，未激活的账号同样占用它。它只承担「指认」，不证明来者持有这个账号——那是凭据的事。它不是 AccountId：不得出现在 TenantId 中，也不得作为任何归属记录的键。本版无变更路径。",
      "$comment": "它的对外形式（是否邮箱、是否允许大小写差异）本版未定，与 G-04 同属 realization。此处复用 OpaqueIdentifier 只是形状上的最小约束，不表示它对用户不可读。",
      "examples": ["ada@example.invalid"]
    },

    "AccountId": {
      "$ref": "#/$defs/OpaqueIdentifier",
      "title": "账号标识 · Account Id",
      "description": "S-1：账号（UL-account）的标识。不透明、部署内唯一、由存储生成、不回收不复用。相等即同一个账号。跨对象引用一律用它，不用登录标识（S-2）。",
      "examples": ["acc_91ab40"]
    },

    "OrganizationId": {
      "$ref": "#/$defs/OpaqueIdentifier",
      "title": "组织标识 · Organization Id",
      "description": "S-3：组织（UL-organization）的标识。不透明、部署内唯一、由存储生成、不回收不复用。个人组织与团队组织共用同一个标识空间，不能从它的形状分辨变体——要分辨读 OrganizationKind。",
      "examples": ["org_7fd2c1"]
    },

    "LoginStateId": {
      "$ref": "#/$defs/OpaqueIdentifier",
      "title": "登录状态标识 · Login State Id",
      "description": "S-9：登录状态（UL-login-state）的标识。不透明、部署内唯一、由存储生成。每次登录产生新的一个，不复用；它不是会话的标识，也不是账号的标识。产品正文未述登录状态靠什么标识（缺口 G-06），本定义只给出满足「彼此可分辨」的最小形状。",
      "examples": ["lgs_3c7e11"]
    },

    "OrganizationKind": {
      "title": "OrganizationKind",
      "description": "S-4：组织的一项属性，创建时确定、此后不可改、无写路径。它是规格层的判别式名，不是统一语言词条——词表里没有「组织变体」这一条，因此这里刻意不给它「中文 · English」那种词条式标题。它的两个取值各对应一个词条：personal ↔ 个人组织 Personal Organization，team ↔ 团队组织 Team Organization。personal 蕴含一组结构性禁止（恰四条，逐条连同在哪个失败值上兑现，写在 omne-harness-lite-design-2026-09-15 · capability.organization-governance · v1 的 S-6；本契约不自列一份）。本契约只取其数据形状后果：判断这些事读这一个值、不另立标志位；个人组织的上级链恒空，因此任何两个不同的个人组织都不会有共同上级。",
      "$comment": "「personal 蕴含那组禁止」是跨对象约束，Schema 表达不了，归组织治理契约与其结构模型。判别式闭合、未知取值一律拒绝，见 S-32。",
      "type": "string",
      "enum": ["personal", "team"]
    },

    "TenantRole": {
      "title": "租户角色 · Tenant Role",
      "description": "S-8：租户在其组织内的属性，单值，取值恰两种。可变，变更只影响此后的准入判定，不改变已发生的归属与既有事实。superAdministrator 的作用域恰是该组织，不表达任何平台范围的资格。它不进租户身份（见 TenantId）。",
      "type": "string",
      "enum": ["superAdministrator", "member"]
    },

    "TenantId": {
      "title": "租户身份 · Tenant Id",
      "description": "S-5 / S-7：值类型，由 (OrganizationId, AccountId) 这一有序对确定，这是它的唯一规范序列化形式。相等按分量，不存在第三种相等依据。不含角色、不含成员资格、不含时间。S-6：没有生成路径，也没有销毁路径——成员关系的建立与解除改变的是 MembershipStanding，不改变这个值是哪一个，已记录的引用永不悬空。两个分量都必需：缺一即非法值，不得用环境里的当前账号或当前组织补齐（S-12）。",
      "$comment": "本版刻意不定义任何标量形式（拼接串、哈希、编码键都不是），见缺口 G-05。消费者若在实现里需要标量键，不得把它作为身份对外发布，也不得把解析它的结果当作授权依据（S-7、S-34）。additionalProperties: false 同时挡住了「顺手加一个 role 字段」这种最常见的越界。",
      "type": "object",
      "properties": {
        "organization": { "$ref": "#/$defs/OrganizationId" },
        "account": { "$ref": "#/$defs/AccountId" }
      },
      "required": ["organization", "account"],
      "additionalProperties": false,
      "examples": [
        { "organization": "org_7fd2c1", "account": "acc_91ab40" }
      ]
    },

    "MembershipStanding": {
      "title": "成员资格效力 · Membership Standing",
      "description": "S-10：一个租户此刻算不算数（UL-membership-standing），恰两值。effective 表示成员关系成立，并同时给出该租户在其组织内恰持的那一个角色；ineffective 表示从未建立或已被解除。没有「有效但角色未知」这一态。「读不到」不是它的第三个取值——那是读面的失败，见 MembershipStandingResult 与 S-19。token 与词条的对应：effective ↔ 词条的「有效 In force」，ineffective ↔ 「无效 Not in force」。两者不得互相替代——对外文档用词条名，交换表示用 token；token 取「同一词根的正反」这条最不易写错的形状，不必与词条英文同形。",
