    "MessageBase": {
      "title": "消息底座（contract.md S-2）",
      "description": "每一种消息共有的四个成员，都必填：id（S-3）、type（S-1）、blocks（一串内容块，次序有意义，可以是空数组——各种消息另有限制，S-6）、createdAt（S-4，不是次序）。消息不带「给谁看」——那在块上（S-5）。",
      "$comment": "本定义不带 additionalProperties: false——各种消息以 allOf 引用它，并以 unevaluatedProperties: false 闭合自己的成员集合。块的形状整份取自 data.content-blocks v2。",
      "type": "object",
      "properties": {
        "id": { "$ref": "#/$defs/MessageId" },
        "type": { "type": "string" },
        "blocks": {
          "type": "array",
          "items": { "$ref": "../../content-blocks/v2/content-blocks.schema.json#/$defs/ContentBlock" }
        },
        "createdAt": { "$ref": "../../offer-expiry/v1/offer-expiry.schema.json#/$defs/Instant" }
      },
      "required": ["id", "type", "blocks", "createdAt"]
    },

    "SystemMessage": {
      "title": "SystemMessage（contract.md S-7）",
      "description": "系统在开头说的设定：你是谁、你有什么能用（UL-system-prompt）。成分在实例存续期内恒定。不落会话日志，每次组装现算（S-7）——日志里出现它是日志不一致（S-32 ⑦），那是追加一侧的判定，本定义管不到。本版只含文本：块只能是文本块，且不带来路标记（S-6）。",
      "type": "object",
      "allOf": [{ "$ref": "#/$defs/MessageBase" }],
      "properties": {
        "type": { "const": "system" },
        "blocks": {
          "items": {
            "allOf": [
              { "properties": { "kind": { "const": "text" } }, "required": ["kind"] },
              { "not": { "required": ["origin"] } }
            ]
          }
        }
      },
      "unevaluatedProperties": false
    },

    "UserMessage": {
      "title": "UserMessage（contract.md S-8）",
      "description": "人说的话；斜杠命令展开之后的那一条、经连接件送达的外部消息也落成这一种。块里不许有思考、工具调用、工具结果（S-6）；文本块可以带来路标记 origin（UL-origin-tag，data.content-blocks v2 S-8），且只有这一种消息的顶层文本块可以带。",
      "type": "object",
      "allOf": [{ "$ref": "#/$defs/MessageBase" }],
      "properties": {
        "type": { "const": "user" },
        "blocks": {
          "items": {
            "not": { "properties": { "kind": { "enum": ["thinking", "tool_call", "tool_result"] } }, "required": ["kind"] }
          }
        }
      },
      "unevaluatedProperties": false
    },

    "AssistantEnding": {
      "title": "AssistantMessage 怎么收的尾（contract.md S-10）",
      "description": "恰三个取值，闭合：complete——正常收尾；interrupted_by_user——用户发起的停下（直接叫停、插队顺带、用户取消了这次运行），且已有内容到了他眼前；truncated_at_limit——写到上限被截断。流断在半路的另两种情形（用户叫停而什么都没出来、出错断的）与系统发起的运行取消（会话归档、宿主停止或被撤下，在途的流被放弃）不成为消息，所以没有取值。回复流的 finish.reason 怎样对到这里，对应表只在 contract.md S-10。",
      "type": "string",
      "enum": ["complete", "interrupted_by_user", "truncated_at_limit"]
    },

    "AssistantMessage": {
      "title": "AssistantMessage（contract.md S-9、S-10）",
      "description": "模型的回复：一次模型调用成为消息的那一份，只有这一份权威内容。response 指认产出它的那份响应（ResponseId，家在 data.model-response，G-3）；ending 说它怎么收的尾，缺席不当作 complete。块里不许有工具结果、不许有带来路标记的文本（S-6）。ending 为 complete 时不许有没长完的工具调用；ending 不是 complete 时至少一块——什么都还没出来的那种不成为消息。",
      "type": "object",
      "allOf": [
        { "$ref": "#/$defs/MessageBase" },
        {
          "if": { "properties": { "ending": { "const": "complete" } }, "required": ["ending"] },
          "then": {
            "properties": {
              "blocks": {
                "items": {
                  "not": { "properties": { "kind": { "const": "tool_call" }, "complete": { "const": false } }, "required": ["kind", "complete"] }
                }
              }
            }
          }
        },
        {
          "if": { "properties": { "ending": { "enum": ["interrupted_by_user", "truncated_at_limit"] } }, "required": ["ending"] },
          "then": { "properties": { "blocks": { "minItems": 1 } } }
        }
      ],
      "properties": {
        "type": { "const": "assistant" },
        "response": { "$ref": "#/$defs/ResponseId" },
        "ending": { "$ref": "#/$defs/AssistantEnding" },
        "blocks": {
          "items": {
            "allOf": [
              { "not": { "properties": { "kind": { "const": "tool_result" } }, "required": ["kind"] } },
              { "not": { "required": ["origin"] } }
            ]
          }
        }
      },
      "required": ["response", "ending"],
      "unevaluatedProperties": false
    },

    "ToolMessage": {
      "title": "ToolMessage（contract.md S-11）",
      "description": "工具说结果：一次调用恰一条，blocks 恰好一个工具结果块，且它的 callId 与本消息的 callId 相同（后一半 Schema 管不到）；违反即表示层拒绝 tool_message_block_count（S-39）。占位也是这一种——转后台、被中断、异常中断——收场与原因都写在那个工具结果块上（data.content-blocks v2 S-15～S-18）；结果卸载之后带摘要的那一条也是这一种，但它是那次调用的结果、不是占位（S-11）。那一块的 reason.code 不得是 terminated_by_agent——那个原因只落后台执行收场的提醒，写在工具消息上即 malformed（S-11、S-39）。",
      "type": "object",
      "allOf": [{ "$ref": "#/$defs/MessageBase" }],
      "properties": {
        "type": { "const": "tool" },
        "callId": { "$ref": "../../content-blocks/v2/content-blocks.schema.json#/$defs/CallId" },
        "blocks": {
          "minItems": 1,
          "maxItems": 1,
          "items": {
            "allOf": [
              { "$ref": "../../content-blocks/v2/content-blocks.schema.json#/$defs/ToolResultBlock" },
              { "not": { "properties": { "reason": { "properties": { "code": { "const": "terminated_by_agent" } }, "required": ["code"] } }, "required": ["reason"] } }
            ]
          }
        }
      },
      "required": ["callId"],
      "unevaluatedProperties": false
    },

    "ToolInternalEnding": {
      "title": "ToolInternalMessage 怎么收的尾（contract.md S-14）",
      "description": "帧流怎么收的尾，恰三个取值，闭合：complete——产生者正常收尾；interrupted——执行被有意停下，帧流随之收尾；lost——产生者失去连续性（含等待到点没有回答、经 MCP 桥的执行随桥换代没了下文、帧流自己断了、持有装配状态的宿主被撤下时放弃在途的帧流），帧流没有等到它的收尾。帧流的 finish.reason 怎样对到这三个值，对应表只在 contract.md S-14。它不是那次执行的收场——收场在工具消息或后台收场提醒里。",
      "type": "string",
      "enum": ["complete", "interrupted", "lost"]
    },

    "ToolInternalMessage": {
      "title": "ToolInternalMessage（contract.md S-13、S-14）",
      "description": "工具说过程：一次工具执行至多一条，块是它发的帧封口之后的那些块，至少一块。顶层每一块 visibility.toModel 都必须为 false，否则表示层拒绝 tool_internal_block_visible_to_model（S-39）。块里不许有思考、工具调用、工具结果、带来路标记的文本（S-6）。只有收尾之后的那一条进日志；收尾之前拼到一半的是在途状态，不是消息。",
      "type": "object",
      "allOf": [{ "$ref": "#/$defs/MessageBase" }],
      "properties": {
        "type": { "const": "tool_internal" },
        "callId": { "$ref": "../../content-blocks/v2/content-blocks.schema.json#/$defs/CallId" },
        "ending": { "$ref": "#/$defs/ToolInternalEnding" },
        "blocks": {
          "minItems": 1,
          "items": {
            "allOf": [
              { "not": { "properties": { "kind": { "enum": ["thinking", "tool_call", "tool_result"] } }, "required": ["kind"] } },
              { "not": { "required": ["origin"] } },
              { "properties": { "visibility": { "properties": { "toModel": { "const": false } } } } }
            ]
          }
        }
      },
      "required": ["callId", "ending"],
      "unevaluatedProperties": false
    },

    "ReminderNature": {
      "title": "提醒说的是事还是状态（contract.md S-16）",
      "description": "恰两个取值，闭合：event——刚才发生了什么；state——现在什么样。它决定这条提醒必须写出什么（说状态的要交代从什么变成了什么），不决定它在日志里的命运（一律追加）。它与 source.kind 的对应是定死的，对不上即表示层拒绝 reminder_nature_mismatch（S-39）。",
      "type": "string",
      "enum": ["event", "state"]
    },

    "SystemReminderMessage": {
      "title": "SystemReminderMessage（contract.md S-15～S-26）",
      "description": "系统在中途说的话：外面有信息进来了。blocks 是给模型读的话（人也看得到）；source 是结构化的来源（来源标记，UL-source-tag），给系统认——对账、呈现、压缩、循环阶梯都读它，不解析正文。nature 与 source.kind 的对应定死（S-16）。块里不许有思考、工具调用、带来路标记的文本；顶层工具结果块只在后台执行的两种收场提醒里出现，且恰好一块（S-19）。",
      "type": "object",
      "allOf": [
        { "$ref": "#/$defs/MessageBase" },
        {
          "if": {
            "properties": {
              "source": {
                "properties": {
                  "kind": {
                    "enum": [
                      "background_execution_finished",
                      "background_execution_interrupted",
                      "attempt_started",
                      "interrupted",
                      "system_wait_answered",
                      "loop_guard",
                      "peer_session_note",
                      "scheduled_trigger"
                    ]
                  }
                },
                "required": ["kind"]
              }
            },
            "required": ["source"]
          },
          "then": { "properties": { "nature": { "const": "event" } } }
        },
        {
          "if": {
            "properties": {
              "source": {
                "properties": { "kind": { "enum": ["runtime_context_changed", "runtime_context_snapshot"] } },
                "required": ["kind"]
              }
            },
            "required": ["source"]
          },
          "then": { "properties": { "nature": { "const": "state" } } }
        },
        {
          "if": {
            "properties": {
              "source": {
                "properties": { "kind": { "enum": ["background_execution_finished", "background_execution_interrupted"] } },
                "required": ["kind"]
              }
            },
            "required": ["source"]
          },
          "then": {
            "properties": {
              "blocks": {
                "contains": { "properties": { "kind": { "const": "tool_result" } }, "required": ["kind"] },
                "minContains": 1,
                "maxContains": 1
              }
            }
          },
          "else": {
            "properties": {
              "blocks": {
                "items": { "not": { "properties": { "kind": { "const": "tool_result" } }, "required": ["kind"] } }
              }
            }
          }
        },
        {
          "if": {
            "properties": { "source": { "properties": { "kind": { "const": "background_execution_finished" } }, "required": ["kind"] } },
            "required": ["source"]
          },
          "then": {
            "properties": {
              "blocks": {
                "items": {
                  "if": { "properties": { "kind": { "const": "tool_result" } }, "required": ["kind"] },
                  "then": { "properties": { "outcome": { "enum": ["completed", "failed", "interrupted", "no_answer"] } } }
                }
              }
            }
          }
        },
        {
          "if": {
            "properties": { "source": { "properties": { "kind": { "const": "background_execution_interrupted" } }, "required": ["kind"] } },
            "required": ["source"]
          },
          "then": {
            "properties": {
              "blocks": {
                "items": {
                  "if": { "properties": { "kind": { "const": "tool_result" } }, "required": ["kind"] },
                  "then": {
                    "properties": {
                      "outcome": { "const": "failed" },
                      "reason": { "properties": { "code": { "const": "abnormal_interruption" } } }
                    },
                    "required": ["reason"]
                  }
                }
              }
            }
          }
        }
      ],
      "properties": {
        "type": { "const": "system_reminder" },
        "nature": { "$ref": "#/$defs/ReminderNature" },
        "source": { "$ref": "#/$defs/ReminderSource" },
        "blocks": {
          "items": {
            "allOf": [
              { "not": { "properties": { "kind": { "enum": ["thinking", "tool_call"] } }, "required": ["kind"] } },
              { "not": { "required": ["origin"] } }
            ]
          }
        }
      },
      "required": ["nature", "source"],
      "unevaluatedProperties": false
    },

    "ReminderSource": {
      "title": "提醒的来源（contract.md S-18）",
      "description": "封闭的判别联合，按 kind 判别，恰十一种：十种系统自己的来源，外加拓展件追加的 extension 一种兜底。系统自己的来源不许绕过这张表私加（加一种＝改本契约版本）；每一种带自己的结构化成员，成员集合闭合。未知的 kind 是 malformed，不当作 extension。",
      "oneOf": [
        { "$ref": "#/$defs/BackgroundExecutionFinishedSource" },
        { "$ref": "#/$defs/BackgroundExecutionInterruptedSource" },
        { "$ref": "#/$defs/AttemptStartedSource" },
        { "$ref": "#/$defs/InterruptedSource" },
        { "$ref": "#/$defs/SystemWaitAnsweredSource" },
        { "$ref": "#/$defs/LoopGuardSource" },
        { "$ref": "#/$defs/PeerSessionNoteSource" },
        { "$ref": "#/$defs/ScheduledTriggerSource" },
        { "$ref": "#/$defs/RuntimeContextChangedSource" },
        { "$ref": "#/$defs/RuntimeContextSnapshotSource" },
        { "$ref": "#/$defs/ExtensionSource" }
      ]
    },

    "BackgroundExecutionFinishedSource": {
      "title": "后台执行跑到头了（contract.md S-19）",
      "description": "转了后台的那段执行跑到头，真实结果回来了。callId 是那次调用；outcome 是那段执行的收场，只在 completed、failed、interrupted、no_answer 四种里出。结果本身是这条提醒 blocks 里恰好那一个工具结果块，它的 callId 与 outcome 与这里相同（Schema 管不到相等）。说事的。",
      "type": "object",
      "properties": {
        "kind": { "const": "background_execution_finished" },
        "callId": { "$ref": "../../content-blocks/v2/content-blocks.schema.json#/$defs/CallId" },
        "outcome": {
          "allOf": [
            { "$ref": "../../content-blocks/v2/content-blocks.schema.json#/$defs/ExecutionOutcome" },
            { "enum": ["completed", "failed", "interrupted", "no_answer"] }
          ]
        }
      },
      "required": ["kind", "callId", "outcome"],
      "additionalProperties": false
    },

    "BackgroundExecutionInterruptedSource": {
      "title": "后台执行异常中断（contract.md S-19）",
      "description": "恢复对账时由系统代落：转了后台的那段执行没了，也没有它结束时回来的提醒。收场是失败，写给 agent 的原因是异常中断——blocks 里恰好那一个工具结果块写 outcome: failed、reason.code: abnormal_interruption，callId 与这里相同。说事的。",
      "type": "object",
      "properties": {
        "kind": { "const": "background_execution_interrupted" },
        "callId": { "$ref": "../../content-blocks/v2/content-blocks.schema.json#/$defs/CallId" }
      },
      "required": ["kind", "callId"],
      "additionalProperties": false
    },

    "AttemptStartedSource": {
      "title": "一次尝试开始了（contract.md S-20）",
      "description": "这条提醒同时就是日志里的「尝试开始」记录。attempt 是尝试序号（data.call-accounts v2 的 AttemptId，≥ 1），显式写出、不靠数；at 是这次尝试起的时刻；reason 是为什么起，恰三值：first——这个 Run 的第一次尝试；resumed_after_interruption——从一次中断接上来；resumed_after_wait——等到的东西回来了。哪个 Run 由承载它的记录条目给出（G-2）。说事的。",
      "type": "object",
      "properties": {
        "kind": { "const": "attempt_started" },
        "attempt": { "$ref": "../../call-accounts/v2/call-accounts.schema.json#/$defs/AttemptId" },
        "reason": { "type": "string", "enum": ["first", "resumed_after_interruption", "resumed_after_wait"] },
        "at": { "$ref": "../../offer-expiry/v1/offer-expiry.schema.json#/$defs/Instant" }
      },
      "required": ["kind", "attempt", "reason", "at"],
      "additionalProperties": false
    },

    "InterruptedSource": {
      "title": "刚才被中断了（contract.md S-21）",
      "description": "模型调用或整个运行被中断就补一条，哪怕什么内容都没留下。what 是被中断的那一层（model_call、run）——工具执行被中断不另补这条，占位的工具消息就承载它（S-21）；by 是谁发起的（user——用户发起的：叫停、插队顺带、用户取消了这次运行；system——不是用户发起的：出错断、写到上限、系统侧停止，含会话归档、宿主停止或被撤下）；hadContent 是中断之前有没有内容已经到了用户眼前。about 可选，只配 what: model_call：{ kind: model, call: ModelCallId, dispatch } 指一次模型调用的第几次发出——成员名 call 与五种运行时记录的 call 同义，不叫 callId：本契约里 callId 只指工具调用的 CallId（S-21）；what: run 不带 about。说事的。",
      "type": "object",
      "properties": {
        "kind": { "const": "interrupted" },
        "what": { "type": "string", "enum": ["model_call", "run"] },
        "by": { "type": "string", "enum": ["user", "system"] },
        "hadContent": { "type": "boolean" },
        "about": {
          "title": "一次模型调用的一次发出",
          "type": "object",
          "properties": {
            "kind": { "const": "model" },
            "call": { "$ref": "../../call-accounts/v2/call-accounts.schema.json#/$defs/ModelCallId" },
            "dispatch": { "type": "integer", "minimum": 1 }
          },
          "required": ["kind", "call", "dispatch"],
          "additionalProperties": false
        }
      },
      "required": ["kind", "what", "by", "hadContent"],
      "allOf": [
        {
          "if": { "properties": { "what": { "const": "run" } }, "required": ["what"] },
          "then": { "not": { "required": ["about"] } }
        }
      ],
      "additionalProperties": false
    },

    "CardAnswer": {
      "title": "卡片上的一项答复（contract.md S-22；占位形状）",
